import subprocess, json, sys, time, os, threading, select

BIN = os.environ.get("RUSTOWL_BIN", "/workspace/executable")
CWD = os.environ.get("RUSTOWL_CWD", "/tmp/ws")

class LSP:
    def __init__(self, args=None, cwd=CWD, env=None, stderr=True):
        a = [BIN] + (args if args is not None else ["--stdio"])
        e = dict(os.environ)
        if env: e.update(env)
        self.p = subprocess.Popen(a, cwd=cwd, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                  stderr=(subprocess.PIPE if stderr else subprocess.DEVNULL), env=e)
        self.buf = b""
        self.errs = []
        self.msgs = []
        if stderr:
            threading.Thread(target=self._read_err, daemon=True).start()
    def _read_err(self):
        for line in self.p.stderr:
            self.errs.append(line.decode('utf8','replace').rstrip('\n'))
    def send(self, obj):
        b = json.dumps(obj, separators=(',',':')).encode()
        try:
            self.p.stdin.write(b"Content-Length: %d\r\n\r\n"%len(b) + b)
            self.p.stdin.flush()
        except Exception as ex:
            print("send failed", ex)
    def notify(self, method, params):
        self.send({"jsonrpc":"2.0","method":method,"params":params})
    def request(self, id, method, params):
        self.send({"jsonrpc":"2.0","id":id,"method":method,"params":params})
    def _read_raw(self, timeout):
        fd = self.p.stdout.fileno()
        r,_,_ = select.select([fd],[],[],timeout)
        if not r: return b""
        return os.read(fd, 65536)
    def read(self, timeout=5.0):
        end = time.time()+timeout
        while time.time() < end:
            if b"\r\n\r\n" in self.buf:
                head, rest = self.buf.split(b"\r\n\r\n",1)
                hdrs = dict(l.split(": ",1) for l in head.decode().split("\r\n") if ": " in l)
                n = int(hdrs["Content-Length"])
                while len(rest) < n:
                    d = self._read_raw(0.1)
                    if not d: break
                    rest += d
                if len(rest) < n:
                    self.buf = b""
                    return None
                self.buf = rest[n:]
                return json.loads(rest[:n])
            d = self._read_raw(0.1)
            if not d: continue
            self.buf += d
        return None
    def read_all(self, timeout=5.0):
        out=[]; end=time.time()+timeout
        while True:
            rem = end-time.time()
            if rem <= 0: break
            m = self.read(rem)
            if m is None: break
            out.append(m)
        return out
    def close(self):
        try: self.p.stdin.close()
        except Exception: pass
        try: self.p.wait(timeout=3)
        except Exception: self.p.kill()
        return self.p.returncode
    def show(self):
        for e in self.errs: print("E:", e)
        print("OUT:")
        for m in self.msgs: print(json.dumps(m)[:3000])
PYEOF
