//! Serde-like (de)serialization of the LSP parameter types.
//!
//! Error messages are reproduced so that clients see the same diagnostics as
//! they would with the `lsp-types` crate, e.g. ``missing field `line` `` or
//! `invalid type: integer `1`, expected struct HoverParams`.

use crate::json::Json;

pub type De<T> = Result<T, String>;

/// serde-ish description of an unexpected value.
pub fn describe(v: &Json) -> String {
    match v {
        Json::Null => "null".to_string(),
        Json::Bool(b) => format!("boolean `{}`", b),
        Json::Uint(u) => format!("integer `{}`", u),
        Json::Int(i) => format!("integer `{}`", i),
        Json::Float(f) => format!("floating point `{}`", crate::json::Json::Float(*f).to_compact().trim_start_matches("[").trim_end_matches("]")),
        Json::Str(s) => format!("string {}", crate::json::write_string(s)),
        Json::Arr(_) => "sequence".to_string(),
        Json::Obj(_) => "map".to_string(),
    }
}

pub fn invalid(v: &Json, expected: &str) -> String {
    format!("invalid type: {}, expected {}", describe(v), expected)
}

pub fn missing(field: &str) -> String {
    format!("missing field `{}`", field)
}

/// The members of a JSON object, or an error saying the value was not an
/// object of the given (rust) struct name.
pub fn as_struct(v: &Json, name: &str) -> De<&Vec<(String, Json)>> {
    match v.as_obj() {
        Some(o) => Ok(o),
        None => Err(invalid(v, &format!("struct {}", name))),
    }
}

pub fn field_opt<F>(obj: &[(String, Json)], key: &str, f: F) -> De<()>
where
    F: Fn(&Json) -> De<()>,
{
    if let Some((_, v)) = obj.iter().find(|(k, _)| k == key) {
        f(v)?;
    }
    Ok(())
}

pub fn field_req<F>(obj: &[(String, Json)], key: &str, f: F) -> De<()>
where
    F: Fn(&Json) -> De<()>,
{
    match obj.iter().find(|(k, _)| k == key) {
        Some((_, v)) => f(v),
        None => Err(missing(key)),
    }
}

pub fn de_bool(v: &Json) -> De<bool> {
    match v {
        Json::Bool(b) => Ok(*b),
        _ => Err(invalid(v, "a boolean")),
    }
}

pub fn de_string(v: &Json) -> De<String> {
    match v {
        Json::Str(s) => Ok(s.clone()),
        _ => Err(invalid(v, "a string")),
    }
}

pub fn de_u32(v: &Json) -> De<u32> {
    match v {
        Json::Uint(u) => {
            if *u <= u32::MAX as u64 {
                Ok(*u as u32)
            } else {
                Err(format!("invalid value: integer `{}`, expected u32", u))
            }
        }
        Json::Int(i) => Err(format!("invalid value: integer `{}`, expected u32", i)),
        _ => Err(invalid(v, "u32")),
    }
}

pub fn de_f64(v: &Json) -> De<f64> {
    match v {
        Json::Uint(u) => Ok(*u as f64),
        Json::Int(i) => Ok(*i as f64),
        Json::Float(f) => Ok(*f),
        _ => Err(invalid(v, "f64")),
    }
}

pub fn de_string_seq(v: &Json) -> De<Vec<String>> {
    match v {
        Json::Arr(items) => {
            let mut out = Vec::new();
            for it in items {
                out.push(de_string(it)?);
            }
            Ok(out)
        }
        _ => Err(invalid(v, "a sequence")),
    }
}

pub fn de_bool_seq(v: &Json) -> De<Vec<bool>> {
    match v {
        Json::Arr(items) => {
            let mut out = Vec::new();
            for it in items {
                out.push(de_bool(it)?);
            }
            Ok(out)
        }
        _ => Err(invalid(v, "a sequence")),
    }
}

/// `Url` from the `url` crate.
pub fn de_url(v: &Json) -> De<String> {
    let s = match v {
        Json::Str(s) => s.clone(),
        _ => return Err(invalid(v, "a string representing an URL")),
    };
    match crate::url::parse(&s) {
        Ok(()) => Ok(s),
        Err(e) => Err(format!("{}: {}", e, crate::json::Json::Str(s.clone()).to_compact())),
    }
}

