pub fn optional_versioned_text_document_identifier(v: &Json) -> De<()> {
    // `OptionalVersionedTextDocumentIdentifier` is an untagged enum: either a
    // plain identifier or a versioned one.
    match v {
        Json::Obj(_) => {
            let o = as_struct(v, "OptionalVersionedTextDocumentIdentifier")?;
            if o.iter().any(|(k, _)| k == "uri") && !o.iter().any(|(k, _)| k == "version") {
                text_document_identifier(v)
            } else {
                versioned_text_document_identifier(v)
            }
        }
        _ => {
            let _ = text_document_identifier(v);
            let _ = versioned_text_document_identifier(v);
            Err("data did not match any variant of untagged enum OptionalVersionedTextDocumentIdentifier".to_string())
        }
    }
}

