use std::io::Write;

pub const VERSION: &str = "v1.0.0-rc.1";
pub const DISPLAY_NAME: &str = "RustOwl";

pub const BANNER: &str = "RustOwl v1.0.0-rc.1\nThis is an LSP server. You can use --help flag to show help.";

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Shell {
    Bash,
    Elvish,
    Fish,
    PowerShell,
    Zsh,
