//! Command line parsing.
//!
//! The command line interface is generated from the same specification as the
//! original: a root command with an optional subcommand, plus global flags.
//! Help texts, error messages and exit codes follow the ones produced by
//! `clap` for this specification.

use std::io::Write;

pub const VERSION: &str = "v1.0.0-rc.1";
pub const DISPLAY_NAME: &str = "RustOwl";

pub const BANNER: &str = "RustOwl v1.0.0-rc.1\nThis is an LSP server. You can use --help flag to show help.";

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Shell {
    Bash,
    Elvish,
    Fish,
    PowerShell,
    Zsh,
    Nushell,
}

#[derive(Debug)]
pub enum Command {
    /// Run the LSP server (the default action when no subcommand is given).
    Lsp,
    Check {
        path: Option<String>,
        all_targets: bool,
        all_features: bool,
    },
    Clean,
    ToolchainInstall {
        path: Option<String>,
        skip_rustowl_toolchain: bool,
    },
    ToolchainUninstall,
    /// `toolchain` without a subcommand: nothing to do.
    ToolchainNoop,
    Completions(Shell),
}

pub struct Parsed {
    pub quiet: u8,
    pub command: Command,
}

pub struct CliError {
    pub message: String,
}

/// The (sub)command currently being parsed; used to render help and errors.
#[derive(Clone, Copy, PartialEq)]
enum Scope {
    Root,
    Check,
    Clean,
    Toolchain,
    ToolchainInstall,
    ToolchainUninstall,
    Completions,
}

impl Scope {
    fn path(self) -> &'static str {
        match self {
            Scope::Root => "",
            Scope::Check => "check",
            Scope::Clean => "clean",
            Scope::Toolchain => "toolchain",
            Scope::ToolchainInstall => "toolchain install",
            Scope::ToolchainUninstall => "toolchain uninstall",
            Scope::Completions => "completions",
        }
    }
    fn parent(self) -> Scope {
        match self {
            Scope::ToolchainInstall | Scope::ToolchainUninstall => Scope::Toolchain,
            _ => Scope::Root,
        }
    }
}

// ---------------------------------------------------------------------------
// Help texts
// ---------------------------------------------------------------------------

pub fn help_text(bin: &str, scope: Scope, long: bool) -> String {
