// ---------------------------------------------------------------------------
// Usage rendering for errors
// ---------------------------------------------------------------------------

/// The full usage line of a scope (the one printed by `--help`).
fn full_usage(bin: &str, scope: Scope) -> String {
    match scope {
        Scope::Root => format!("{} [OPTIONS] [COMMAND]", bin),
        Scope::Check => format!("{} check [OPTIONS] [path]", bin),
        Scope::Clean => format!("{} clean", bin),
        Scope::Toolchain => format!("{} toolchain [COMMAND]", bin),
        Scope::ToolchainInstall => format!("{} toolchain install [OPTIONS]", bin),
        Scope::ToolchainUninstall => format!("{} toolchain uninstall", bin),
        Scope::Completions => format!("{} completions <SHELL>", bin),
    }
}

fn positionals(scope: Scope, used: bool) -> &'static str {
    match scope {
        Scope::Check => {
            if used {
                "<path>"
            } else {
                "[path]"
            }
        }
        Scope::Completions => "<SHELL>",
        _ => "",
    }
}

/// "smart" usage: the scope path plus everything that was already consumed.
fn smart_usage(bin: &str, scope: Scope, used: &[String], positional_used: bool) -> String {
    let mut parts: Vec<String> = Vec::new();
    if scope == Scope::Root {
        parts.push(bin.to_string());
    } else {
        parts.push(bin.to_string());
        parts.push(scope.path().to_string());
    }
    for u in used {
        parts.push(u.clone());
    }
    let p = positionals(scope, positional_used);
    if !p.is_empty() {
        parts.push(p.to_string());
    }
    parts.join(" ")
}

fn print_help(bin: &str, scope: Scope, long: bool) -> ! {
    let text = help_text(bin, scope, long);
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(text.as_bytes());
    let _ = lock.flush();
    std::process::exit(0);
}

fn fail(body: &str, usage: Option<&str>) -> ! {
    let mut out = String::new();
    out.push_str("error: ");
    out.push_str(body);
    out.push('\n');
    if let Some(u) = usage {
        out.push('\n');
        out.push_str("Usage: ");
        out.push_str(u);
        out.push('\n');
    }
    out.push_str("\nFor more information, try '--help'.\n");
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
    std::process::exit(2);
}

fn scope_subcommands(scope: Scope) -> &'static [&'static str] {
    match scope {
        Scope::Root => &["check", "clean", "toolchain", "completions", "help"],
        Scope::Toolchain => &["install", "uninstall", "help"],
        _ => &[],
    }
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

pub fn parse(bin: &str, args: &[String]) -> Parsed {
    let mut quiet: u8 = 0;
    let mut stdio = false;
    let mut want_version = false;
    let mut used: Vec<String> = Vec::new();
    let mut positional_used = false;
    let mut scope = Scope::Root;
    let mut escaped = false;

    let mut all_targets = false;
    let mut all_features = false;
    let mut path: Option<String> = None;
    let mut install_path: Option<String> = None;
    let mut install_path_seen = false;
    let mut skip_rustowl = false;
    let mut shell: Option<Shell> = None;
    let mut help_args: Vec<String> = Vec::new();

    let mut i = 0usize;
    while i < args.len() {
        let arg = args[i].clone();
        i += 1;

        if escaped {
            // everything after `--` is a positional value
            handle_positional(
                bin,
                &mut scope,
                &arg,
                &mut path,
                &mut shell,
                &mut positional_used,
                &mut help_args,
                &mut used,
                true,
            );
            escaped = false;
            continue;
        }

        if arg.starts_with("--") && arg.len() > 2 {
            let (name, value) = match arg.split_once('=') {
                Some((n, v)) => (n.to_string(), Some(v.to_string())),
                None => (arg.clone(), None),
            };
            match scope {
                Scope::Root => match name.as_str() {
                    "--version" => {
                        if value.is_some() {
                            let used2 = render_used(&used, "--quiet...");
                            let _ = used2;
                            used.push("--version".to_string());
                            let u = smart_usage(bin, scope, &used, positional_used);
                            fail(
                                &format!(
                                    "unexpected value '{}' for '--version' found; no more were expected",
                                    value.unwrap()
                                ),
                                Some(&u),
                            );
                        }
                        want_version = true;
                        used.push("--version".to_string());
                    }
                    "--quiet" => {
                        if let Some(v) = value {
                            used.push("--quiet...".to_string());
                            let u = smart_usage(bin, scope, &used, positional_used);
                            fail(
                                &format!(
                                    "unexpected value '{}' for '--quiet...' found; no more were expected",
                                    v
                                ),
                                Some(&u),
                            );
                        }
                        quiet += 1;
                        if !used.iter().any(|u| u == "--quiet...") {
                            used.push("--quiet...".to_string());
                        }
                    }
                    "--stdio" => {
                        if let Some(v) = value {
                            used.push("--stdio".to_string());
                            let u = smart_usage(bin, scope, &used, positional_used);
                            fail(
                                &format!(
                                    "unexpected value '{}' for '--stdio' found; no more were expected",
                                    v
                                ),
                                Some(&u),
                            );
                        }
                        stdio = true;
                        used.push("--stdio".to_string());
                    }
                    "--help" => print_help(bin, scope, true),
                    "--" => {
                        escaped = true;
                    }
                    other => {
                        unexpected_argument(bin, scope, other, &used, positional_used, true);
                    }
                },
                Scope::Check => match name.as_str() {
                    "--all-targets" => {
                        if let Some(v) = value {
                            used.push("--all-targets".to_string());
                            let u = smart_usage(bin, scope, &used, positional_used);
                            fail(
                                &format!(
                                    "unexpected value '{}' for '--all-targets' found; no more were expected",
                                    v
                                ),
                                Some(&u),
                            );
                        }
                        all_targets = true;
                        used.push("--all-targets".to_string());
                    }
                    "--all-features" => {
                        if let Some(v) = value {
                            used.push("--all-features".to_string());
                            let u = smart_usage(bin, scope, &used, positional_used);
                            fail(
                                &format!(
                                    "unexpected value '{}' for '--all-features' found; no more were expected",
                                    v
                                ),
                                Some(&u),
                            );
                        }
                        all_features = true;
                        used.push("--all-features".to_string());
                    }
                    "--help" => print_help(bin, scope, true),
                    "--" => {
                        escaped = true;
                    }
                    other => {
                        unexpected_argument(bin, scope, other, &used, positional_used, true);
                    }
                },
                Scope::ToolchainInstall => match name.as_str() {
                    "--path" => {
                        match value {
                            Some(v) => {
                                if install_path_seen {
                                    let u = full_usage(bin, scope);
                                    fail(
                                        "the argument '--path <path>' cannot be used multiple times",
                                        Some(&u),
                                    );
                                }
                                install_path_seen = true;
                                install_path = Some(v);
                                used.push("--path <path>".to_string());
                            }
                            None => fail(
                                "a value is required for '--path <path>' but none was supplied",
                                None,
                            ),
                        }
                    }
                    "--skip-rustowl-toolchain" => {
                        if let Some(v) = value {
                            used.push("--skip-rustowl-toolchain".to_string());
                            let u = smart_usage(bin, scope, &used, positional_used);
                            fail(
                                &format!(
                                    "unexpected value '{}' for '--skip-rustowl-toolchain' found; no more were expected",
                                    v
                                ),
                                Some(&u),
                            );
                        }
                        skip_rustowl = true;
                        used.push("--skip-rustowl-toolchain".to_string());
                    }
                    "--help" => print_help(bin, scope, true),
                    "--" => {
                        escaped = true;
                    }
                    other => {
                        unexpected_argument(bin, scope, other, &used, positional_used, false);
                    }
                },
                Scope::Toolchain => match name.as_str() {
                    "--help" => print_help(bin, scope, true),
                    "--" => {
                        escaped = true;
                    }
                    other => {
                        unexpected_argument(bin, scope, other, &used, positional_used, false);
                    }
                },
                Scope::Clean | Scope::ToolchainUninstall => match name.as_str() {
                    "--help" => print_help(bin, scope, true),
                    "--" => {
                        escaped = true;
                    }
                    other => {
                        unexpected_argument(bin, scope, other, &used, positional_used, false);
                    }
                },
                Scope::Completions => match name.as_str() {
                    "--help" => print_help(bin, scope, true),
                    "--" => {
                        escaped = true;
                    }
                    other => {
                        unexpected_argument(bin, scope, other, &used, positional_used, true);
                    }
                },
            }
            continue;
        }

        if arg.starts_with('-') && arg.len() > 1 {
            // short flag cluster
            for c in arg[1..].chars() {
                match c {
                    'h' => print_help(bin, scope, false),
                    'V' => {
                        want_version = true;
                        if scope == Scope::Root && !used.iter().any(|u| u == "--version") {
                            used.push("--version".to_string());
                        }
                    }
                    'q' if scope == Scope::Root => {
                        quiet += 1;
                        if !used.iter().any(|u| u == "--quiet...") {
                            used.push("--quiet...".to_string());
                        }
                    }
                    other => {
                        unexpected_argument(bin, scope, &format!("-{}", other), &used, positional_used, true);
                    }
                }
            }
            continue;
        }

        // positional
        handle_positional(
            bin,
            &mut scope,
            &arg,
            &mut path,
            &mut shell,
            &mut positional_used,
            &mut help_args,
            &mut used,
            false,
        );
    }

    // `help` subcommand resolution
    if scope == Scope::Root && !help_args.is_empty() {
        let scope = help_scope(bin, &help_args);
        if let Some(s) = scope {
            print_help(bin, s, true);
        }
    }

    if want_version {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let text = if quiet > 0 {
            format!("{}\n", VERSION)
        } else {
            format!("{} {}\n", DISPLAY_NAME, VERSION)
        };
        let _ = lock.write_all(text.as_bytes());
        let _ = lock.flush();
        std::process::exit(0);
    }

    let command = match scope {
        Scope::Root => Command::Lsp,
        Scope::Check => Command::Check {
            path,
            all_targets,
            all_features,
        },
        Scope::Clean => Command::Clean,
        Scope::Toolchain => Command::ToolchainNoop,
        Scope::ToolchainInstall => Command::ToolchainInstall {
            path: install_path,
            skip_rustowl_toolchain: skip_rustowl,
        },
        Scope::ToolchainUninstall => Command::ToolchainUninstall,
        Scope::Completions => Command::Completions(shell.unwrap()),
    };

    Parsed { quiet, command }
}

fn render_used(used: &[String], extra: &str) -> Vec<String> {
    let mut v: Vec<String> = used.to_vec();
    v.push(extra.to_string());
    v
}

/// Handle a positional argument in the current scope.
#[allow(clippy::too_many_arguments)]
fn handle_positional(
    bin: &str,
    scope: &mut Scope,
    arg: &str,
    path: &mut Option<String>,
    shell: &mut Option<Shell>,
    positional_used: &mut bool,
    help_args: &mut Vec<String>,
    used: &mut Vec<String>,
    after_escaped: bool,
) {
    let subs = scope_subcommands(*scope);
    match scope {
        Scope::Root => {
            if !after_escaped && subs.contains(&arg) {
                match arg {
                    "check" => *scope = Scope::Check,
                    "clean" => *scope = Scope::Clean,
                    "toolchain" => *scope = Scope::Toolchain,
                    "completions" => *scope = Scope::Completions,
                    "help" => {
                        // the remaining arguments name the sub command
                        help_args.clear();
                        help_args.push(arg.to_string());
                        *scope = Scope::ToolchainInstall; // marker, replaced below
                        // handled by setting a special flag
                        *scope = Scope::Root;
                        *positional_used = false;
                        // We need a way to know we are inside `help`: use a
                        // dedicated marker below.
                        HELP_ACTIVE.with(|c| c.set(true));
                        return;
                    }
                    _ => unreachable!(),
                }
                used.clear();
                *positional_used = false;
                return;
            }
            if !after_escaped && arg == "help" {
                HELP_ACTIVE.with(|c| c.set(true));
                return;
            }
            if after_escaped && subs.contains(&arg) {
                let u = full_usage(bin, *scope);
                fail(
                    &format!(
                        "unexpected argument '{}' found\n\n  tip: subcommand '{}' exists; to use it, remove the '--' before it",
                        arg, arg
                    ),
                    Some(&u),
                );
            }
            let u = full_usage(bin, *scope);
            fail(
                &format!("unrecognized subcommand '{}'", arg),
                Some(&u),
            );
        }
        Scope::Check => {
            if path.is_none() {
                *path = Some(arg.to_string());
                *positional_used = true;
                if !used.iter().any(|u| u == "path") {
                    // positional arguments are tracked for usage rendering
                    used.push("path".to_string());
                }
            } else {
                let u = full_usage(bin, *scope);
                fail(&format!("unexpected argument '{}' found", arg), Some(&u));
            }
        }
        Scope::Completions => {
            if shell.is_none() {
                let value = match arg {
                    "bash" => Shell::Bash,
                    "elvish" => Shell::Elvish,
                    "fish" => Shell::Fish,
                    "powershell" => Shell::PowerShell,
                    "zsh" => Shell::Zsh,
                    "nushell" => Shell::Nushell,
                    _ => fail(
                        &format!(
                            "invalid value '{}' for '<SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh, nushell]",
                            arg
                        ),
                        None,
                    ),
                };
                *shell = Some(value);
                *positional_used = true;
                if !used.iter().any(|u| u == "path") {
                    used.push("path".to_string());
                }
            } else {
                let u = full_usage(bin, *scope);
                fail(&format!("unexpected argument '{}' found", arg), Some(&u));
            }
        }
        Scope::Toolchain => {
            if !after_escaped && subs.contains(&arg) {
                match arg {
                    "install" => *scope = Scope::ToolchainInstall,
                    "uninstall" => *scope = Scope::ToolchainUninstall,
                    "help" => {
                        HELP_ACTIVE.with(|c| c.set(true));
                        HELP_SCOPE.with(|c| c.set(Scope::Toolchain));
                        return;
                    }
                    _ => unreachable!(),
                }
                used.clear();
                *positional_used = false;
                return;
            }
            let u = full_usage(bin, *scope);
            fail(&format!("unrecognized subcommand '{}'", arg), Some(&u));
        }
        _ => {
            let u = full_usage(bin, *scope);
            fail(&format!("unexpected argument '{}' found", arg), Some(&u));
        }
    }
}

thread_local! {
    static HELP_ACTIVE: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    static HELP_SCOPE: std::cell::Cell<Option<Scope>> = const { std::cell::Cell::new(None) };
}

fn help_scope(bin: &str, args: &[String]) -> Option<Scope> {
    let mut scope = Scope::Root;
    for a in &args[1..] {
        let subs = scope_subcommands(scope);
        if subs.contains(&a.as_str()) {
            scope = match (scope, a.as_str()) {
                (Scope::Root, "check") => Scope::Check,
                (Scope::Root, "clean") => Scope::Clean,
                (Scope::Root, "toolchain") => Scope::Toolchain,
                (Scope::Root, "completions") => Scope::Completions,
                (Scope::Toolchain, "install") => Scope::ToolchainInstall,
                (Scope::Toolchain, "uninstall") => Scope::ToolchainUninstall,
                _ => unreachable!(),
            };
        } else {
            let u = full_usage(bin, scope);
            fail(&format!("unrecognized subcommand '{}'", a), Some(&u));
        }
    }
    Some(scope)
}

fn unexpected_argument(
    bin: &str,
    scope: Scope,
    name: &str,
    used: &[String],
    positional_used: bool,
    has_positional: bool,
) -> ! {
    let shown: Vec<String> = used
        .iter()
        .filter(|u| u.as_str() != "path")
        .cloned()
        .collect();
    let usage = if shown.is_empty() && !positional_used {
        full_usage(bin, scope)
    } else {
        smart_usage(bin, scope, &shown, positional_used)
    };
    let mut body = format!("unexpected argument '{}' found", name);
    if has_positional {
        body.push_str(&format!(
            "\n\n  tip: to pass '{}' as a value, use '-- {}'",
            name, name
        ));
    }
    fail(&body, Some(&usage));
}
