//! Command line parsing.
//!
//! The interface is a root command with an optional subcommand and global
//! flags. Help texts, error messages and exit codes reproduce the ones the
//! argument parser generates for this specification.

use std::io::Write;

pub const VERSION: &str = "v1.0.0-rc.1";
pub const DISPLAY_NAME: &str = "RustOwl";

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Shell {
    Bash,
    Elvish,
    Fish,
    PowerShell,
    Zsh,
    Nushell,
}

#[derive(Debug)]
pub enum Command {
    /// Run the LSP server (the default when no subcommand is given).
    Lsp,
    Check {
        path: Option<String>,
        all_targets: bool,
        all_features: bool,
    },
    Clean,
    ToolchainInstall {
        path: Option<String>,
        skip_rustowl_toolchain: bool,
    },
    ToolchainUninstall,
    /// `toolchain` without a subcommand: nothing to do.
    ToolchainNoop,
    Completions(Shell),
}

pub struct Parsed {
    pub quiet: u8,
    pub command: Command,
}

#[derive(Clone, Copy, PartialEq)]
enum Scope {
    Root,
    Check,
    Clean,
    Toolchain,
    ToolchainInstall,
    ToolchainUninstall,
    Completions,
}

impl Scope {
    fn path(self) -> &'static str {
        match self {
            Scope::Root => "",
            Scope::Check => "check",
            Scope::Clean => "clean",
            Scope::Toolchain => "toolchain",
            Scope::ToolchainInstall => "toolchain install",
            Scope::ToolchainUninstall => "toolchain uninstall",
            Scope::Completions => "completions",
        }
    }
    fn subcommands(self) -> &'static [&'static str] {
        match self {
            Scope::Root => &["check", "clean", "toolchain", "completions", "help"],
            Scope::Toolchain => &["install", "uninstall", "help"],
            _ => &[],
        }
    }
    fn has_positional(self) -> bool {
        matches!(self, Scope::Check | Scope::Completions)
    }
}

// ---------------------------------------------------------------------------
// Help texts
// ---------------------------------------------------------------------------

pub fn help_text(bin: &str, scope: Scope, long: bool) -> String {
    match scope {
        Scope::Root => format!(
            "Usage: {bin} [OPTIONS] [COMMAND]\n\n\
             Commands:\n\
             \x20 check        Check availability\n\
             \x20 clean        Remove artifacts from the target directory\n\
             \x20 toolchain    Install or uninstall the toolchain\n\
             \x20 completions  Generate shell completions\n\
             \x20 help         Print this message or the help of the given subcommand(s)\n\n\
             Options:\n\
             \x20 -V, --version   Print version\n\
             \x20 -q, --quiet...  Suppress output\n\
             \x20     --stdio     Use stdio to communicate with the LSP server\n\
             \x20 -h, --help      Print help\n"
        ),
        Scope::Check => format!(
            "Check availability\n\n\
             Usage: {bin} check [OPTIONS] [path]\n\n\
             Arguments:\n\
             \x20 [path]  The path of a file or directory to check availability\n\n\
             Options:\n\
             \x20     --all-targets   Run the check for all targets instead of current only\n\
             \x20     --all-features  Run the check for all features instead of the current active ones only\n\
             \x20 -h, --help          Print help\n"
        ),
        Scope::Clean => format!(
            "Remove artifacts from the target directory\n\n\
             Usage: {bin} clean\n\n\
             Options:\n\
             \x20 -h, --help  Print help\n"
        ),
        Scope::Toolchain => format!(
            "Install or uninstall the toolchain\n\n\
             Usage: {bin} toolchain [COMMAND]\n\n\
             Commands:\n\
             \x20 install    Install the toolchain\n\
             \x20 uninstall  Uninstall the toolchain\n\
             \x20 help       Print this message or the help of the given subcommand(s)\n\n\
             Options:\n\
             \x20 -h, --help  Print help\n"
        ),
        Scope::ToolchainInstall => format!(
            "Install the toolchain\n\n\
             Usage: {bin} toolchain install [OPTIONS]\n\n\
             Options:\n\
             \x20     --path <path>             Runtime directory path to install RustOwl toolchain\n\
             \x20     --skip-rustowl-toolchain  Install Rust toolchain only\n\
             \x20 -h, --help                    Print help\n"
        ),
        Scope::ToolchainUninstall => format!(
            "Uninstall the toolchain\n\n\
             Usage: {bin} toolchain uninstall\n\n\
             Options:\n\
             \x20 -h, --help  Print help\n"
        ),
        Scope::Completions => {
            if long {
                format!(
                    "Generate shell completions\n\n\
                     Usage: {bin} completions <SHELL>\n\n\
                     Arguments:\n\
                     \x20 <SHELL>\n\
                     \x20         The shell to generate completions for\n\n\
                     \x20         Possible values:\n\
                     \x20         - bash:       Bourne Again `SHell` (bash)\n\
                     \x20         - elvish:     Elvish shell\n\
                     \x20         - fish:       Friendly Interactive `SHell` (fish)\n\
                     \x20         - powershell: `PowerShell`\n\
                     \x20         - zsh:        Z `SHell` (zsh)\n\
                     \x20         - nushell:    Nushell\n\n\
                     Options:\n\
                     \x20 -h, --help\n\
                     \x20         Print help (see a summary with '-h')\n"
                )
            } else {
                format!(
                    "Generate shell completions\n\n\
                     Usage: {bin} completions <SHELL>\n\n\
                     Arguments:\n\
                     \x20 <SHELL>  The shell to generate completions for [possible values: bash, elvish, fish, powershell, zsh, nushell]\n\n\
                     Options:\n\
                     \x20 -h, --help  Print help (see more with '--help')\n"
                )
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Usage rendering
// ---------------------------------------------------------------------------

fn full_usage(bin: &str, scope: Scope) -> String {
    match scope {
        Scope::Root => format!("{} [OPTIONS] [COMMAND]", bin),
        Scope::Check => format!("{} check [OPTIONS] [path]", bin),
        Scope::Clean => format!("{} clean", bin),
        Scope::Toolchain => format!("{} toolchain [COMMAND]", bin),
        Scope::ToolchainInstall => format!("{} toolchain install [OPTIONS]", bin),
        Scope::ToolchainUninstall => format!("{} toolchain uninstall", bin),
        Scope::Completions => format!("{} completions <SHELL>", bin),
    }
}

fn positional_placeholder(scope: Scope, used: bool) -> &'static str {
    match scope {
        Scope::Check => {
            if used {
                "<path>"
            } else {
                "[path]"
            }
        }
        Scope::Completions => "<SHELL>",
        _ => "",
    }
}

fn smart_usage(bin: &str, scope: Scope, used: &[String], positional_used: bool) -> String {
    let mut parts: Vec<String> = vec![bin.to_string()];
    if scope != Scope::Root {
        parts.push(scope.path().to_string());
    }
    for u in used {
        parts.push(u.clone());
    }
    let p = positional_placeholder(scope, positional_used);
    if !p.is_empty() {
        parts.push(p.to_string());
    }
    parts.join(" ")
}

fn print_help(bin: &str, scope: Scope, long: bool) -> ! {
    let text = help_text(bin, scope, long);
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(text.as_bytes());
    let _ = lock.flush();
    std::process::exit(0);
}

fn fail(body: &str, usage: Option<&str>) -> ! {
    let mut out = String::new();
    out.push_str("error: ");
    out.push_str(body);
    out.push('\n');
    if let Some(u) = usage {
        out.push('\n');
        out.push_str("Usage: ");
        out.push_str(u);
        out.push('\n');
    }
    out.push_str("\nFor more information, try '--help'.\n");
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
    std::process::exit(2);
}

fn unexpected_argument(
    bin: &str,
    scope: Scope,
    name: &str,
    used: &[String],
    positional_used: bool,
    add_tip: bool,
) -> ! {
    let usage = if used.is_empty() && !positional_used {
        full_usage(bin, scope)
    } else {
        smart_usage(bin, scope, used, positional_used)
    };
    let mut body = format!("unexpected argument '{}' found", name);
    if add_tip {
        body.push_str(&format!(
            "\n\n  tip: to pass '{}' as a value, use '-- {}'",
            name, name
        ));
    }
    fail(&body, Some(&usage));
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

#[derive(Default)]
struct State {
    quiet: u8,
    stdio: bool,
    want_version: bool,
    used: Vec<String>,
    positional_used: bool,
    scope: Scope,
    escaped: bool,
    help_mode: Option<Scope>,
    help_args: Vec<String>,
    // check
    all_targets: bool,
    all_features: bool,
    path: Option<String>,
    // toolchain install
    install_path: Option<String>,
    install_path_seen: bool,
    skip_rustowl: bool,
    // completions
    shell: Option<Shell>,
}

pub fn parse(bin: &str, args: &[String]) -> Parsed {
    let mut st = State::default();

    let mut i = 0usize;
    while i < args.len() {
        let arg = args[i].clone();
        i += 1;

        // inside `help ...` every argument is a subcommand name
        if let Some(_hs) = st.help_mode {
            st.help_args.push(arg);
            continue;
        }

        if st.escaped {
            positional(bin, &mut st, &arg, true);
            st.escaped = false;
            continue;
        }

        if arg.starts_with("--") && arg.len() > 2 {
            let (name, value) = match arg.split_once('=') {
                Some((n, v)) => (n.to_string(), Some(v.to_string())),
                None => (arg.clone(), None),
            };
            if name == "--" {
                st.escaped = true;
                continue;
            }
            match st.scope {
                Scope::Root => match name.as_str() {
                    "--version" => flag_no_value(bin, &mut st, "--version", "--version", value),
                    "--quiet" => flag_no_value(bin, &mut st, "--quiet", "--quiet...", value),
                    "--stdio" => flag_no_value(bin, &mut st, "--stdio", "--stdio", value),
                    "--help" => print_help(bin, st.scope, true),
                    other => unexpected_argument(bin, st.scope, other, &st.used, st.positional_used, false),
                },
                Scope::Check => match name.as_str() {
                    "--all-targets" => flag_no_value(bin, &mut st, "--all-targets", "--all-targets", value),
                    "--all-features" => flag_no_value(bin, &mut st, "--all-features", "--all-features", value),
                    "--help" => print_help(bin, st.scope, true),
                    other => unexpected_argument(bin, st.scope, other, &st.used, st.positional_used, true),
                },
                Scope::ToolchainInstall => match name.as_str() {
                    "--path" => match value {
                        Some(v) => {
                            if st.install_path_seen {
                                let u = full_usage(bin, st.scope);
                                fail(
                                    "the argument '--path <path>' cannot be used multiple times",
                                    Some(&u),
                                );
                            }
                            st.install_path_seen = true;
                            st.install_path = Some(v);
                            st.used.push("--path <path>".to_string());
                        }
                        None => fail(
                            "a value is required for '--path <path>' but none was supplied",
                            None,
                        ),
                    },
                    "--skip-rustowl-toolchain" => flag_no_value(
                        bin,
                        &mut st,
                        "--skip-rustowl-toolchain",
                        "--skip-rustowl-toolchain",
                        value,
                    ),
                    "--help" => print_help(bin, st.scope, true),
                    other => unexpected_argument(bin, st.scope, other, &st.used, st.positional_used, false),
                },
                Scope::Completions => match name.as_str() {
                    "--help" => print_help(bin, st.scope, true),
                    other => unexpected_argument(bin, st.scope, other, &st.used, st.positional_used, true),
                },
                _ => match name.as_str() {
                    "--help" => print_help(bin, st.scope, true),
                    other => unexpected_argument(bin, st.scope, other, &st.used, st.positional_used, false),
                },
            }
            continue;
        }

        if arg.starts_with('-') && arg.len() > 1 {
            for c in arg[1..].chars() {
                match c {
                    'h' => print_help(bin, st.scope, false),
                    'V' => {
                        st.want_version = true;
                        if st.scope == Scope::Root && !st.used.iter().any(|u| u == "--version") {
                            st.used.push("--version".to_string());
                        }
                    }
                    'q' if st.scope == Scope::Root => {
                        st.quiet += 1;
                        if !st.used.iter().any(|u| u == "--quiet...") {
                            st.used.push("--quiet...".to_string());
                        }
                    }
                    other => unexpected_argument(
                        bin,
                        st.scope,
                        &format!("-{}", other),
                        &st.used,
                        st.positional_used,
                        st.scope.has_positional(),
                    ),
                }
            }
            continue;
        }

        positional(bin, &mut st, &arg, false);
    }

    if let Some(scope) = st.help_mode {
        resolve_help(bin, scope, &st.help_args);
    }

    if st.want_version {
        let text = if st.quiet > 0 {
            format!("{}\n", crate::cli::VERSION)
        } else {
            format!("{} {}\n", crate::cli::DISPLAY_NAME, crate::cli::VERSION)
        };
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = lock.write_all(text.as_bytes());
        let _ = lock.flush();
        std::process::exit(0);
    }

    let command = match st.scope {
        Scope::Root => Command::Lsp,
        Scope::Check => Command::Check {
            path: st.path,
            all_targets: st.all_targets,
            all_features: st.all_features,
        },
        Scope::Clean => Command::Clean,
        Scope::Toolchain => Command::ToolchainNoop,
        Scope::ToolchainInstall => Command::ToolchainInstall {
            path: st.install_path,
            skip_rustowl_toolchain: st.skip_rustowl,
        },
        Scope::ToolchainUninstall => Command::ToolchainUninstall,
        Scope::Completions => Command::Completions(st.shell.unwrap()),
    };
    Parsed {
        quiet: st.quiet,
        command,
    }
}

/// A boolean flag that does not take a value.
fn flag_no_value(
    bin: &str,
    st: &mut State,
    arg: &str,
    rendered: &str,
    value: Option<String>,
) {
    match value {
        Some(v) => {
            if !st.used.iter().any(|u| u == rendered) {
                st.used.push(rendered.to_string());
            }
            let u = smart_usage(bin, st.scope, &st.used, st.positional_used);
            fail(
                &format!(
                    "unexpected value '{}' for '{}' found; no more were expected",
                    v,
                    rendered
                ),
                Some(&u),
            );
        }
        None => {
            if !st.used.iter().any(|u| u == rendered) {
                st.used.push(rendered.to_string());
            }
            match arg {
                "--version" => st.want_version = true,
                "--quiet" => st.quiet += 1,
                "--stdio" => st.stdio = true,
                "--all-targets" => st.all_targets = true,
                "--all-features" => st.all_features = true,
                "--skip-rustowl-toolchain" => st.skip_rustowl = true,
                _ => {}
            }
        }
    }
}

fn positional(bin: &str, st: &mut State, arg: &str, after_escaped: bool) {
    let subs = st.scope.subcommands();
    match st.scope {
        Scope::Root => {
            if !after_escaped && subs.contains(&arg) {
                match arg {
                    "check" => st.scope = Scope::Check,
                    "clean" => st.scope = Scope::Clean,
                    "toolchain" => st.scope = Scope::Toolchain,
                    "completions" => st.scope = Scope::Completions,
                    "help" => {
                        st.help_mode = Some(Scope::Root);
                        st.help_args = vec![arg.to_string()];
                        st.used.clear();
                        st.positional_used = false;
                        return;
                    }
                    _ => unreachable!(),
                }
                st.used.clear();
                st.positional_used = false;
                return;
            }
            if after_escaped && subs.contains(&arg) {
                let u = full_usage(bin, st.scope);
                fail(
                    &format!(
                        "unexpected argument '{}' found\n\n  tip: subcommand '{}' exists; to use it, remove the '--' before it",
                        arg, arg
                    ),
                    Some(&u),
                );
            }
            let u = full_usage(bin, st.scope);
            fail(&format!("unrecognized subcommand '{}'", arg), Some(&u));
        }
        Scope::Toolchain => {
            if !after_escaped && subs.contains(&arg) {
                match arg {
                    "install" => st.scope = Scope::ToolchainInstall,
                    "uninstall" => st.scope = Scope::ToolchainUninstall,
                    "help" => {
                        st.help_mode = Some(Scope::Toolchain);
                        st.help_args = vec![arg.to_string()];
                        st.used.clear();
                        st.positional_used = false;
                        return;
                    }
                    _ => unreachable!(),
                }
                st.used.clear();
                st.positional_used = false;
                return;
            }
            let u = full_usage(bin, st.scope);
            fail(&format!("unrecognized subcommand '{}'", arg), Some(&u));
        }
        Scope::Check => {
            if st.path.is_none() {
                st.path = Some(arg.to_string());
                st.positional_used = true;
            } else {
                let u = full_usage(bin, st.scope);
                fail(&format!("unexpected argument '{}' found", arg), Some(&u));
            }
        }
        Scope::Completions => {
            if st.shell.is_none() {
                st.shell = Some(match arg {
                    "bash" => Shell::Bash,
                    "elvish" => Shell::Elvish,
                    "fish" => Shell::Fish,
                    "powershell" => Shell::PowerShell,
                    "zsh" => Shell::Zsh,
                    "nushell" => Shell::Nushell,
                    _ => fail(
                        &format!(
                            "invalid value '{}' for '<SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh, nushell]",
                            arg
                        ),
                        None,
                    ),
                });
                st.positional_used = true;
            } else {
                let u = full_usage(bin, st.scope);
                fail(&format!("unexpected argument '{}' found", arg), Some(&u));
            }
        }
        _ => {
            let u = full_usage(bin, st.scope);
            fail(&format!("unexpected argument '{}' found", arg), Some(&u));
        }
    }
}

fn resolve_help(bin: &str, scope: Scope, args: &[String]) -> ! {
    let mut scope = scope;
    for a in &args[1..] {
        let subs = scope.subcommands();
        if subs.contains(&a.as_str()) {
            scope = match (scope, a.as_str()) {
                (Scope::Root, "check") => Scope::Check,
                (Scope::Root, "clean") => Scope::Clean,
                (Scope::Root, "toolchain") => Scope::Toolchain,
                (Scope::Root, "completions") => Scope::Completions,
                (Scope::Toolchain, "install") => Scope::ToolchainInstall,
                (Scope::Toolchain, "uninstall") => Scope::ToolchainUninstall,
                _ => unreachable!(),
            };
        } else {
            let u = full_usage(bin, scope);
            fail(&format!("unrecognized subcommand '{}'", a), Some(&u));
        }
    }
    print_help(bin, scope, true)
}
RSEOF
echo ok

