//! A very small URL validator.
//!
//! Only enough of RFC 3986 is implemented to classify the input the same way
//! the `url` crate does for the values that appear in LSP payloads.

const SPECIAL: [&str; 6] = ["http", "https", "ws", "wss", "ftp", "file"];

pub fn parse(s: &str) -> Result<(), &'static str> {
    let bytes = s.as_bytes();
    // scheme = ALPHA *( ALPHA / DIGIT / "+" / "-" / "." )
    let mut scheme_end = None;
    for (i, c) in s.char_indices() {
        match c {
            'a'..='z' | 'A'..='Z' => {
                if i == 0 {
                    continue;
                }
            }
            '0'..='9' | '+' | '-' | '.' => {
                if i == 0 {
                    break;
                }
            }
            ':' => {
                if i == 0 {
                    break;
                }
                scheme_end = Some(i);
                break;
            }
            _ => break,
        }
    }
    let scheme_end = match scheme_end {
        Some(i) => i,
        None => return Err("relative URL without a base"),
    };
    let scheme = s[..scheme_end].to_ascii_lowercase();
    let rest = &s[scheme_end + 1..];
    if !SPECIAL.contains(&scheme.as_str()) {
        return Ok(());
    }
    let rest = match rest.strip_prefix("//") {
        Some(r) => r,
        None => {
            // `file:/tmp/x` is accepted, other special schemes need `//`
            if scheme == "file" {
                return Ok(());
            }
            return Err("relative URL without a base");
        }
    };
    // authority is up to the first '/', '?' or '#'
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    // strip userinfo
    let authority = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    if authority.is_empty() {
        if scheme == "file" {
            return Ok(());
        }
        return Err("empty host");
    }
    // split off the port (or IPv6 literal)
    let host_port = authority;
    if let Some(stripped) = host_port.strip_prefix('[') {
        let close = match stripped.find(']') {
            Some(i) => i,
            None => return Err("invalid IPv6 address"),
        };
        let after = &stripped[close + 1..];
        if !after.is_empty() {
            let port = after.strip_prefix(':').unwrap_or(after);
            if !valid_port(port) {
                return Err("invalid port number");
            }
        }
        return Ok(());
    }
    let (host, port) = match host_port.rfind(':') {
        Some(i) => (&host_port[..i], Some(&host_port[i + 1..])),
        None => (host_port, None),
    };
    if let Some(port) = port {
        if !valid_port(port) {
            return Err("invalid port number");
        }
    }
    for c in host.chars() {
        if c.is_ascii_alphanumeric() || "-._~%[]".contains(c) {
            continue;
        }
        return Err("invalid international domain name");
    }
    Ok(())
}

fn valid_port(port: &str) -> bool {
    if port.is_empty() {
        return true;
    }
    match port.parse::<u32>() {
        Ok(p) => (1..=65535).contains(&p),
        Err(_) => false,
    }
}
