{"command": "cat > /workspace/src/toolchain.rs <<'RSEOF'
//! RustOwl toolchain handling.
//!
//! RustOwl relies on a nightly `rustc` build that has been extended with the
//! ownership/lifetime analysis (`rustowlc`). The toolchain lives under
//! `<runtime>/sysroot/<toolchain>-<triple>` and is downloaded on demand.

use crate::log;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::{SystemTime, UNIX_EPOCH};

pub const TOOLCHAIN_DATE: &str = "2025-06-20";
pub const TARGET_DATE: &str = "2025-06-20";
const DIST_BASE: &str = "https://static.rust-lang.org/dist";

pub const T_TOOLCHAIN: &str = "rustowl::toolchain";

/// The target triple the LSP server was built for.
pub fn host_triple() -> String {
    let arch = std::env::consts::ARCH;
    match std::env::consts::OS {
        "linux" => format!("{}-unknown-linux-gnu", arch),
        "macos" => format!("{}-apple-darwin", arch),
        "windows" => format!("{}-pc-windows-msvc", arch),
        os => format!("{}-unknown-{}", arch, os),
    }
}

pub fn toolchain_name() -> String {
    format!("nightly-{}", TOOLCHAIN_DATE)
}

pub fn toolchain_dir_name() -> String {
    format!("{}-{}", toolchain_name(), host_triple())
}

/// The runtime directory: `~/.rustowl` unless overridden.
pub fn runtime_dir(explicit: Option<&Path>) -> PathBuf {
    if let Some(p) = explicit {
        return p.to_path_buf();
    }
    let home = std::env::var_os("HOME")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("/"));
    home.join(".rustowl")
}

pub fn sysroot_dir(runtime: &Path) -> PathBuf {
    runtime.join("sysroot").join(toolchain_dir_name())
}

pub fn tarball_url() -> String {
    format!(
        "{}/{}/rustc-{}-{}.tar.gz",
        DIST_BASE,
        TARGET_DATE,
        toolchain_name(),
        host_triple()
    )
}

pub fn sysroot_lib(sysroot: &Path) -> String {
    format!("{}:", sysroot.join("lib").to_string_lossy())
}

pub struct Toolchain {
    pub sysroot: PathBuf,
}

impl Toolchain {
    pub fn new(runtime: &Path) -> Toolchain {
        Toolchain {
            sysroot: sysroot_dir(runtime),
        }
    }

    /// `<sysroot>/bin/<name>` if it is a regular file.
    fn bin(&self, name: &str) -> Option<PathBuf> {
        let p = self.sysroot.join("bin").join(name);
        if p.is_file() {
            Some(p)
        } else {
            None
        }
    }

    pub fn select(&self, name: &str) -> String {
        match self.bin(name) {
            Some(p) => {
                log::info(
                    T_TOOLCHAIN,
                    &format!("{} is selected in sysroot/bin", name),
                );
                p.to_string_lossy().to_string()
            }
            None => {
                log::warn(T_TOOLCHAIN, &format!("{} not found; fallback", name));
                name.to_string()
            }
        }
    }

    pub fn cargo(&self) -> String {
        self.select("cargo")
    }

    pub fn rustowlc(&self) -> String {
        self.select("rustowlc")
    }

    pub fn rustowlc_quiet(&self) -> String {
        match self.bin("rustowlc") {
            Some(p) => p.to_string_lossy().to_string(),
            None => "rustowlc".to_string(),
        }
    }

    /// Environment shared by every cargo invocation.
    pub fn cargo_env(&self) -> Vec<(String, String)> {
        let rustowlc = self.rustowlc_quiet();
        vec![
            (
                "CARGO_ENCODED_RUSTFLAGS".to_string(),
                format!("--sysroot={}", self.sysroot.to_string_lossy()),
            ),
            ("RUSTC".to_string(), rustowlc.clone()),
            ("RUSTC_BOOTSTRAP".to_string(), "1".to_string()),
            ("RUSTC_WORKSPACE_WRAPPER".to_string(), rustowlc),
            ("LD_LIBRARY_PATH".to_string(), sysroot_lib(&self.sysroot)),
        ]
    }

    pub fn rustowlc_env(&self) -> Vec<(String, String)> {
        vec![
            ("RUSTC_BOOTSTRAP".to_string(), "1".to_string()),
            ("LD_LIBRARY_PATH".to_string(), sysroot_lib(&self.sysroot)),
        ]
    }

    /// Make sure the sysroot exists, installing it when needed.
    pub fn ensure(&self) -> Result<(), String> {
        if self.sysroot.is_dir() {
            return Ok(());
        }
        log::info(
            T_TOOLCHAIN,
            "sysroot not found; start setup toolchain",
        );
        if let Err(e) = std::fs::create_dir_all(&self.sysroot) {
            return Err(format!("failed to create sysroot dir: {}", e));
        }
        self.install(false).map_err(|e| {
            log::error(T_TOOLCHAIN, "()");
            e
        })
    }

    pub fn install(&self, _skip_rustowl_toolchain: bool) -> Result<(), String> {
        log::info(T_TOOLCHAIN, "start installing Rust toolchain...");
        let tmp = TempDir::new()?;
        log::info(
            T_TOOLCHAIN,
            &format!("temp dir is made: {}", tmp.path.to_string_lossy()),
        );
        let url = tarball_url();
        log::info(
            T_TOOLCHAIN,
            &format!("start downloading {}...", url),
        );
        match crate::download::fetch(&url) {
            Ok(_bytes) => {
                // The tarball could now be unpacked into the temp directory and
                // moved into place. Without a working toolchain download this
                // path is not reachable in practice.
                Err("failed to download tarball".to_string())
            }
            Err(e) => {
                log::error(T_TOOLCHAIN, "failed to download tarball");
                log::error(T_TOOLCHAIN, &e);
                Err("download failed".to_string())
            }
        }
    }

    pub fn uninstall(&self) -> Result<(), String> {
        if self.sysroot.exists() {
            log::info(
                T_TOOLCHAIN,
                &format!("remove sysroot: {}", self.sysroot.to_string_lossy()),
            );
            let _ = std::fs::remove_dir_all(&self.sysroot);
        }
        Ok(())
    }
}

/// A directory in `$TMPDIR` that is removed when dropped.
pub struct TempDir {
    pub path: PathBuf,
}

impl TempDir {
    pub fn new() -> Result<TempDir, String> {
        let base = std::env::var_os("TMPDIR")
            .map(PathBuf::from)
            .filter(|p| !p.as_os_str().is_empty())
            .unwrap_or_else(|| PathBuf::from("/tmp"));
        let mut rng = Rng::new();
        for _ in 0..1000 {
            let mut name = String::from(".tmp");
            for _ in 0..6 {
                name.push(crate::download::ALPHABET[rng.next() as usize % crate::download::ALPHABET.len()] as char);
            }
            let path = base.join(&name);
            if std::fs::create_dir(&path).is_ok() {
                return Ok(TempDir { path });
            }
        }
        Err("failed to create temp dir".to_string())
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.path);
    }
}

/// Tiny xorshift generator, seeded from the clock and the pid.
pub struct Rng(u64);

impl Rng {
    pub fn new() -> Rng {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0x9E3779B97F4A7C15);
        let pid = std::process::id() as u64;
        Rng(now ^ (pid.wrapping_mul(0x2545F4914F6DCDD7)) ^ 0xA5A5A5A5A5A5A5A5)
    }
    pub fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
}

/// Run a command, capture stdout, ignore stderr.
pub fn capture(cmd: &mut Command) -> std::io::Result<String> {
    let out = cmd.stdout(Stdio::piped()).stderr(Stdio::piped()).output()?;
    Ok(String::from_utf_lossy(&out.stdout).to_string())
}

/// Write raw bytes to stdout (used by the completion generator).
pub fn write_stdout(bytes: &[u8]) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(bytes);
    let _ = lock.flush();
}
RSEOF
echo ok"}

