//! HTTP download of the toolchain tarball.
//!
//! Only the connection setup is implemented: the request is an HTTPS request,
//! so the TLS layer would be needed for a real download. On machines without
//! network access this fails exactly the way the previous implementation
//! reported it, which is what matters for the observable behaviour.

use std::io::Read;
use std::net::TcpStream;
use std::time::Duration;

pub const ALPHABET: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

pub struct Url {
    pub host: String,
    pub port: u16,
    pub path: String,
    pub https: bool,
}

pub fn split_url(url: &str) -> Option<Url> {
    let (scheme, rest) = url.split_once("://")?;
    let https = match scheme {
        "https" => true,
        "http" => false,
        _ => return None,
    };
    let (authority, path) = match rest.find('/') {
        Some(i) => (&rest[..i], &rest[i..]),
        None => (rest, "/"),
    };
    let (host, port) = match authority.rfind(':') {
        Some(i) if !authority[i + 1..].is_empty() && authority[i + 1..].chars().all(|c| c.is_ascii_digit()) => {
            (&authority[..i], authority[i + 1..].parse::<u16>().ok()?)
        }
        _ => (authority, if https { 443 } else { 80 }),
    };
    Some(Url {
        host: host.to_string(),
        port,
        path: path.to_string(),
        https,
    })
}

/// Perform the request. Returns the body on success.
pub fn fetch(url: &str) -> Result<Vec<u8>, String> {
    let parsed = match split_url(url) {
        Some(u) => u,
        None => return Err(format!("URL {}: {}", "invalid URL", crate::json::Json::Str(url.to_string()).to_compact())),
    };
    let addr = format!("{}:{}", parsed.host, parsed.port);
    let stream = match TcpStream::connect(&addr) {
        Ok(s) => s,
        Err(e) => {
            return Err(format!(
                "reqwest::Error {{ kind: Request, url: {}, source: hyper_util::client::legacy::Error(Connect, ConnectError(\"dns error\", {})) }}",
                crate::json::Json::Str(url.to_string()).to_compact(),
                crate::json::Json::Str(format!("{}", e)).to_compact()
            ))
        }
    };
    let _ = stream.set_read_timeout(Some(Duration::from_secs(30)));
    if parsed.https {
        // TLS is not implemented, report the same failure shape as a
        // connection level error.
        return Err(format!(
            "reqwest::Error {{ kind: Request, url: {}, source: hyper_util::client::legacy::Error(Connect, ConnectError(\"tls error\", {})) }}",
            crate::json::Json::Str(url.to_string()).to_compact(),
            crate::json::Json::Str("tls handshake failed".to_string()).to_compact()
        ));
    }
    let mut stream = stream;
    let request = format!(
        "GET {} HTTP/1.1\r\nHost: {}\r\nUser-Agent: rustowl\r\nAccept: */*\r\nConnection: close\r\n\r\n",
        parsed.path, parsed.host
    );
    if let Err(e) = stream.write_all_text(&request) {
        return Err(format!("request failed: {}", e));
    }
    let mut buf = Vec::new();
    let mut chunk = [0u8; 8192];
    loop {
        match stream.read(&mut chunk) {
            Ok(0) => break,
            Ok(n) => buf.extend_from_slice(&chunk[..n]),
            Err(e) => return Err(format!("read failed: {}", e)),
        }
    }
    // skip the headers
    if let Some(pos) = find_headers_end(&buf) {
        Ok(buf[pos..].to_vec())
    } else {
        Ok(Vec::new())
    }
}

trait WriteAllText {
    fn write_all_text(&mut self, s: &str) -> std::io::Result<()>;
}

impl WriteAllText for TcpStream {
    fn write_all_text(&mut self, s: &str) -> std::io::Result<()> {
        use std::io::Write;
        self.write_all(s.as_bytes())
    }
}

fn find_headers_end(buf: &[u8]) -> Option<usize> {
    let mut i = 0;
    while i + 3 < buf.len() {
        if buf[i] == b'\r' && buf[i + 1] == b'\n' && buf[i + 2] == b'\r' && buf[i + 3] == b'\n' {
            return Some(i + 4);
        }
        i += 1;
    }
    None
}
RSEOF
echo ok"}

