    Some(Metadata {
        workspace_root: ws_root,
        packages,
    })
}

/// Resolve the analysis target from a user supplied path.
pub fn resolve(toolchain: &Toolchain, passed: &Path) -> Resolved {
    let metadata = if passed.exists() {
        let cwd = if passed.is_dir() {
            passed.to_path_buf()
        } else {
            passed
                .parent()
                .map(|p| p.to_path_buf())
                .unwrap_or_else(|| PathBuf::from(""))
        };
        cargo_metadata(toolchain, &cwd)
    } else {
        None
    };
    match metadata {
        Some(m) => {
            let manifest = m.workspace_root.join("Cargo.toml");
            match m
                .packages
                .iter()
                .find(|(p, _)| *p == manifest)
                .map(|(_, n)| n.clone())
            {
                Some(name) => Resolved {
                    target: Target::Package { name },
                    workspace_root: Some(m.workspace_root),
                    passed: passed.to_path_buf(),
                },
                None => Resolved {
                    target: Target::Dir(m.workspace_root),
                    workspace_root: Some(m.workspace_root),
                    passed: passed.to_path_buf(),
                },
            }
        }
        None => Resolved {
            target: Target::File(passed.to_path_buf()),
            workspace_root: None,
            passed: passed.to_path_buf(),
        },
    }
}

impl Resolved {
    pub fn is_valid(&self) -> bool {
        match &self.target {
            Target::Package { .. } | Target::Dir(_) => true,
            Target::File(p) => p.is_file() && p.extension().map(|e| e == "rs").unwrap_or(false),
        }
    }

    /// The string used in the "start analyzing" log line.
    pub fn describe(&self) -> String {
        match &self.target {
            Target::Package { name } => format!("package {}", name),
            Target::Dir(p) => p.to_string_lossy().to_string(),
            Target::File(p) => p.to_string_lossy().to_string(),
        }
    }
}

/// The analysis that failed to spawn `rustowlc` panics, exactly like the
/// original does.
fn panic_on_spawn(location: &str) {
    let msg = "\nthread 'tokio-runtime-worker' panicked at {}:\n\
               called `Result::unwrap()` on an `Err` value: Os { code: 2, kind: NotFound, \
               message: \"No such file or directory\" }\n\
               note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n";
    eprintln!("{}", msg.replace("{}", location));
}

/// Run `rustowlc --sysroot=... --crate-type=lib -o/dev/null <path>` and read
/// its stdout.
fn run_rustowlc(toolchain: &Toolchain, path: &Path, verbose: bool, location: &str) {
    let rustowlc = toolchain.rustowlc();
    let mut cmd = Command::new(&rustowlc);
    cmd.arg(format!("--sysroot={}", toolchain.sysroot.to_string_lossy()))
        .arg("--crate-type=lib")
        .arg("-o/dev/null")
        .arg(path)
        .env("RUSTC_BOOTSTRAP", "1")
        .env(
            "LD_LIBRARY_PATH",
            crate::toolchain::sysroot_lib(&toolchain.sysroot),
        )
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit());
    let child = match cmd.spawn() {
        Ok(c) => c,
        Err(_) => {
            panic_on_spawn(location);
            return;
        }
    };
    if verbose {
        log::info(T_ANALYZE, &format!("start analyzing {}", path.to_string_lossy()));
    }
    read_lines(child, verbose);
}

/// Read one line at a time from a child's stdout until it closes.
fn read_lines(mut child: std::process::Child, verbose: bool) {
    if let Some(mut out) = child.stdout.take() {
        use std::io::BufRead;
        let mut reader = std::io::BufReader::new(out);
        let mut line = String::new();
        loop {
            line.clear();
            match reader.read_line(&mut line) {
                Ok(0) => break,
                Ok(_) => {
                    let trimmed = line.trim_end_matches(['\n', '\r']);
                    if let Ok(value) = json::parse(trimmed.as_bytes()) {
                        if value.str_field("reason") == Some("compiler-artifact") {
                            if let Some(name) = value
                                .get("target")
                                .and_then(|t| t.str_field("name"))
                            {
                                if verbose {
                                    log::info(
                                        T_ANALYZE,
                                        &format!("crate {} checked", name),
                                    );
                                }
                            }
                        }
                    }
                }
                Err(_) => break,
            }
        }
    }
    let _ = child.wait();
    if verbose {
        log::info(T_ANALYZE, "stdout closed");
    }
}

/// The full analysis for one target. Returns true when highlights were
/// produced (never in practice without a working toolchain).
pub fn analyze(
    toolchain: &Toolchain,
    resolved: &Resolved,
    all_targets: bool,
    all_features: bool,
    verbose: bool,
    location: &str,
) -> bool {
    match (&resolved.target, &resolved.workspace_root) {
        (Target::Package { name }, Some(ws_root)) => {
            if verbose {
                log::info(T_ANALYZE, "clear cargo cache");
            }
            let cargo = toolchain.cargo();
            let mut clean = Command::new(&cargo);
            clean
                .arg("clean")
                .arg("--package")
                .arg(name)
                .envs(toolchain.cargo_env())
                .current_dir(ws_root)
                .stdout(Stdio::piped())
                .stderr(Stdio::piped());
            if let Ok(mut child) = clean.spawn() {
                let _ = child.wait();
            }
            let mut check = Command::new(&cargo);
            check.arg("check").arg("--workspace");
            if all_targets {
                check.arg("--all-targets");
            }
            if all_features {
                check.arg("--all-features");
            }
            check
                .arg("--keep-going")
                .arg("--message-format=json")
                .envs(toolchain.cargo_env())
                .current_dir(ws_root)
                .stdout(Stdio::piped())
                .stderr(Stdio::piped());
            let child = match check.spawn() {
                Ok(c) => c,
                Err(_) => return false,
            };
            if verbose {
                log::info(T_ANALYZE, &format!("start analyzing {}", resolved.describe()));
            }
            read_lines(child, verbose);
            false
        }
        (Target::Dir(p), _) => {
            run_rustowlc(toolchain, p, verbose, location);
            false
        }
        (Target::File(p), _) => {
            run_rustowlc(toolchain, p, verbose, location);
            false
        }
        _ => false,
    }
}

/// Sleep for the "wait for rust-analyzer" period.
pub fn wait_for_backend() {
    thread::sleep(Duration::from_millis(100));
}
