    fn send(&mut self, body: &str) {
        let bytes = body.as_bytes();
        let header = format!("Content-Length: {}\r\n\r\n", bytes.len());
        let _ = self.out.write_all(header.as_bytes());
        let _ = self.out.write_all(bytes);
        let _ = self.out.flush();
    }
    fn respond(&mut self, id: &Json, body: &Json) {
        let mut obj = Json::obj();
        obj.insert("jsonrpc", Json::Str("2.0".to_string()));
        obj.insert("result", body.clone());
        obj.insert("id", id.clone());
        self.send(&obj.to_compact());
    }
    fn error(&mut self, id: &Json, code: i64, message: &str, data: Option<&str>) {
        let mut err = Json::obj();
        err.insert("code", Json::Int(code));
        err.insert("message", Json::Str(message.to_string()));
        if let Some(d) = data {
            err.insert("data", Json::Str(d.to_string()));
        }
        let mut obj = Json::obj();
        obj.insert("jsonrpc", Json::Str("2.0".to_string()));
        obj.insert("error", err);
        obj.insert("id", id.clone());
        self.send(&obj.to_compact());
    }
}

pub struct Server {
    pub writer: Writer,
    pub initialized: bool,
    pub shutdown: bool,
    pub exiting: bool,
    pub toolchain: Toolchain,
    pub root: Option<String>,
    pub all_targets: bool,
    pub all_features: bool,
}

impl Server {
    fn new() -> Server {
        let runtime = crate::toolchain::runtime_dir(None);
        Server {
            writer: Writer::new(),
            initialized: false,
            shutdown: false,
            exiting: false,
            toolchain: Toolchain::new(&runtime),
            root: None,
            all_targets: false,
            all_features: false,
        }
    }
}

/// Read one framed message from stdin. `Ok(None)` means end of input.
fn read_frame(input: &mut dyn Read) -> Result<Option<Vec<u8>>, ()> {
    let mut headers: Vec<u8> = Vec::new();
    let mut byte = [0u8; 1];
    loop {
        match input.read(&mut byte) {
            Ok(0) => return Ok(None),
            Ok(_) => {
                headers.push(byte[0]);
                if headers.len() >= 4
                    && &headers[headers.len() - 4..] == b"\r\n\r\n"
                {
                    break;
                }
            }
            Err(_) => return Err(()),
        }
    }
    let text = String::from_utf8_lossy(&headers).to_string();
    let mut length: Option<usize> = None;
    for line in text.split("\r\n") {
        if let Some(rest) = line.strip_prefix("Content-Length:") {
            if let Ok(n) = rest.trim().parse::<usize>() {
                length = Some(n);
            }
        }
    }
    let n = match length {
        Some(n) => n,
        None => return Err(()),
    };
    let mut body = vec![0u8; n];
    let mut read = 0;
    while read < n {
        match input.read(&mut body[read..]) {
            Ok(0) => return Ok(None),
            Ok(m) => read += m,
            Err(_) => return Err(()),
        }
    }
    Ok(Some(body))
}

fn request_id(value: &Json) -> Option<Json> {
    match value {
        Json::Null => Some(Json::Null),
        Json::Uint(_) | Json::Int(_) | Json::Str(_) => Some(value.clone()),
        _ => None,
    }
}

/// Analyze the workspace in the background, exactly like the original does.
fn start_analysis(server: &Arc<std::sync::Mutex<Server>>) {
    let state = server.clone();
    std::thread::spawn(move || {
        let guard = state.lock().unwrap();
        let root = guard.root.clone();
        let all_targets = guard.all_targets;
        let all_features = guard.all_features;
        let toolchain = Toolchain::new(&crate::toolchain::runtime_dir(None));
        drop(guard);
        if let Err(_e) = toolchain.ensure() {
            return;
        }
        toolchain.cargo();
        toolchain.rustowlc();
        let passed = match root {
            Some(r) => std::path::PathBuf::from(r),
            None => std::env::current_dir().unwrap_or_default(),
        };
        crate::analyze::wait_for_backend();
        let resolved = crate::analyze::resolve(&toolchain, &passed);
        if !resolved.is_valid() {
            log::warn(
                crate::analyze::T_ANALYZE,
                &format!(
                    "Invalid analysis target: {}",
                    passed.to_string_lossy()
                ),
            );
            return;
        }
        crate::analyze::analyze(
            &toolchain,
            &resolved,
            all_targets,
            all_features,
            false,
            "src/lsp/analyze.rs:222:41",
        );
    });
}

pub fn run() {
    eprint!("{}\n", crate::cli::BANNER);
    let _ = std::io::stderr().flush();

    let server = Arc::new(std::sync::Mutex::new(Server::new()));
    let stdin = std::io::stdin();
    let mut input = stdin.lock();

    loop {
        let frame = match read_frame(&mut input) {
            Ok(f) => f,
            Err(_) => {
                let mut s = server.lock().unwrap();
                s.writer.error(
                    &Json::Null,
                    CODE_PARSE_ERROR,
                    "Parse error",
                    None,
                );
                exit(0);
            }
        };
        let body = match frame {
            Some(b) => b,
            None => break,
        };
        let value = match json::parse(&body) {
            Ok(v) => v,
            Err(_) => {
                let mut s = server.lock().unwrap();
                s.writer.error(&Json::Null, CODE_PARSE_ERROR, "Parse error", None);
                exit(0);
            }
        };
        handle(&server, value);
    }
}

fn handle(server: &Arc<std::sync::Mutex<Server>>, value: Json) {
    let id = value.get("id").cloned();
    // server -> client responses are ignored
    if value.get("result").is_some() || value.get("error").is_some() {
        return;
    }
    let id_json = match &id {
        Some(i) => request_id(i),
        None => None,
    };
    let bad_jsonrpc = match value.get("jsonrpc") {
        Some(Json::Str(s)) => s != "2.0",
        _ => true,
    };
    if bad_jsonrpc {
        let mut s = server.lock().unwrap();
        s.writer
            .error(&Json::Null, CODE_INVALID_REQUEST, "Invalid request", None);
        return;
    }
    let method = value.str_field("method").unwrap_or("").to_string();
    let params = value.get("params").cloned();
    let is_request = id_json.is_some();

    if method.starts_with("$/") {
        if is_request && method == "$/cancelRequest" {
            let mut s = server.lock().unwrap();
            s.writer
                .error(&Json::Null, CODE_INVALID_REQUEST, "Invalid request", None);
        }
        return;
    }

    if !is_request {
        handle_notification(server, &method, params);
        return;
    }
    let id = id_json.unwrap();

    // unknown methods are rejected before the state checks
    let known_request = spec_for(&method).is_some();
    let known_notification = KNOWN_NOTIFICATIONS.contains(&method.as_str());
    if !known_request && !known_notification && method != "initialize" && method != "shutdown" {
        let mut s = server.lock().unwrap();
        s.writer.error(
            &id,
            CODE_METHOD_NOT_FOUND,
            "Method not found",
            Some(&method),
        );
        return;
    }

    let mut s = server.lock().unwrap();
    if !s.initialized {
        if method == "initialize" {
            handle_initialize(&mut s, id, params);
        } else {
            s.writer.error(
                &id,
                CODE_SERVER_NOT_INITIALIZED,
                "Server not initialized",
                None,
            );
        }
        return;
    }
    if method == "initialize" {
        s.writer
            .error(&id, CODE_INVALID_REQUEST, "Invalid request", None);
        return;
    }
    if s.shutdown {
        s.writer
            .error(&id, CODE_INVALID_REQUEST, "Invalid request", None);
        return;
    }
    if method == "shutdown" {
        s.shutdown = true;
        match params {
            None => s.writer.respond(&id, &Json::Null),
            Some(p) => s.writer.error(
                &id,
                CODE_INVALID_PARAMS,
                &format!("Unexpected params: {}", p.to_compact()),
                None,
            ),
        }
        return;
    }
    if known_notification {
        s.writer
            .error(&id, CODE_INVALID_REQUEST, "Invalid request", None);
        return;
    }
    // a known request: validate the parameters, then report that the handler
    // is not implemented
    let spec = spec_for(&method).unwrap();
    let params_value = match params {
        Some(p) => p,
        None => {
            s.writer
                .error(&id, CODE_INVALID_PARAMS, "Missing params field", None);
            return;
        }
    };
    match validate(&params_value, spec) {
        Ok(()) => {
            s.writer
                .error(&id, CODE_METHOD_NOT_FOUND, "Method not found", None);
        }
        Err(e) => {
            s.writer.error(&id, CODE_INVALID_PARAMS, &e, None);
        }
    }
}

fn validate(v: &Json, spec: &Spec) -> De<()> {
    let obj = match v.as_obj() {
        Some(o) => o,
        None => return Err(ty::invalid(v, &format!("struct {}", spec.name))),
    };
    for (key, f) in spec.required {
        ty::field_req(obj, key, *f)?;
    }
    for (key, f) in spec.optional {
        ty::field_opt(obj, key, *f)?;
    }
    Ok(())
}

fn handle_initialize(s: &mut Server, id: Json, params: Option<Json>) {
    let params = match params {
        Some(p) => p,
        None => {
            s.writer
                .error(&id, CODE_INVALID_PARAMS, "Missing params field", None);
            return;
        }
    };
    if params.as_obj().is_none() {
        s.writer
            .error(&id, CODE_INVALID_REQUEST, "Invalid request", None);
        return;
    }
    if let Err(e) = ty::initialize_params(&params) {
        s.writer.error(&id, CODE_INVALID_PARAMS, &e, None);
        return;
    }
    s.initialized = true;
    s.root = params.str_field("rootUri").map(|u| crate::url::to_path(u));
    let _ = params.str_field("rootPath").map(|p| {
        if s.root.is_none() {
            s.root = Some(p.to_string());
        }
    });
    let _ = params.get("workspaceFolders").and_then(|v| match v {
        Json::Arr(list) => list
            .first()
            .and_then(|f| f.str_field("uri"))
            .map(|u| {
                if s.root.is_none() {
                    s.root = Some(crate::url::to_path(u));
                }
            }),
        _ => None,
    });
    let mut capabilities = Json::obj();
    let mut sync = Json::obj();
    sync.insert("change", Json::Uint(2));
    sync.insert("openClose", Json::Bool(true));
    sync.insert("save", Json::Bool(true));
    capabilities.insert("textDocumentSync", sync);
    let mut workspace = Json::obj();
    let mut folders = Json::obj();
    folders.insert("changeNotifications", Json::Bool(true));
    folders.insert("supported", Json::Bool(true));
    workspace.insert("workspaceFolders", folders);
    capabilities.insert("workspace", workspace);
    let mut result = Json::obj();
    result.insert("capabilities", capabilities);
    s.writer.respond(&id, &result);
    drop(s);
    start_analysis(server);
}

fn handle_notification(server: &Arc<std::sync::Mutex<Server>>, method: &str, params: Option<Json>) {
    if server.lock().unwrap().exiting {
        return;
    }
    match method {
        "exit" => {
            let mut s = server.lock().unwrap();
            s.exiting = true;
        }
        "initialized" | "textDocument/didChange" | "textDocument/didSave"
        | "textDocument/didClose" | "textDocument/willSave" => {}
        "workspace/didChangeConfiguration" | "workspace/didChangeWatchedFiles"
        | "workspace/didCreateFiles" | "workspace/didRenameFiles"
        | "workspace/didDeleteFiles" => {}
        "workspace/didChangeWorkspaceFolders" => {
            if server.lock().unwrap().initialized {
                validate_notification(server, method, params);
            }
        }
        "textDocument/didOpen" => {
            if server.lock().unwrap().initialized {
                validate_notification(server, method, params);
            }
        }
        _ => {}
    }
}

fn validate_notification(server: &Arc<std::sync::Mutex<Server>>, method: &str, params: Option<Json>) {
    let ok = match (&method, &params) {
        ("textDocument/didOpen", Some(p)) => ty::did_open_params(p).is_ok(),
        ("workspace/didChangeWorkspaceFolders", Some(p)) => {
            ty::did_change_workspace_folders_params(p).is_ok()
        }
        _ => false,
    };
    if !ok {
        return;
    }
    start_analysis(server);
}
