//! The language server: JSON-RPC framing and request dispatch.

use crate::json::{self, Json};
use crate::log;
use crate::toolchain::Toolchain;
use crate::types::{self as ty, De};
use std::io::{Read, Write};
use std::process::exit;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

pub const CODE_PARSE_ERROR: i64 = -32700;
pub const CODE_INVALID_REQUEST: i64 = -32600;
pub const CODE_METHOD_NOT_FOUND: i64 = -32601;
pub const CODE_INVALID_PARAMS: i64 = -32602;
pub const CODE_SERVER_NOT_INITIALIZED: i64 = -32002;
pub const CODE_CANCELLED: i64 = -32800;

/// Methods the server knows about but never answers with data.
const KNOWN_NOTIFICATIONS: &[&str] = &[
    "initialized",
    "textDocument/didOpen",
    "textDocument/didChange",
    "textDocument/didSave",
    "textDocument/didClose",
    "textDocument/willSave",
    "workspace/didChangeConfiguration",
    "workspace/didChangeWatchedFiles",
    "workspace/didChangeWorkspaceFolders",
    "workspace/didCreateFiles",
    "workspace/didRenameFiles",
    "workspace/didDeleteFiles",
    "$/cancelRequest",
    "exit",
];

/// Request methods: the parameters are validated, the handlers themselves are
/// not implemented.
struct Spec {
    name: &'static str,
    required: &'static [(&'static str, fn(&Json) -> De<()>)],
    optional: &'static [(&'static str, fn(&Json) -> De<()>)],
}

const POSITION: fn(&Json) -> De<()> = ty::position;
const RANGE: fn(&Json) -> De<()> = ty::range;
const TEXT_DOCUMENT: fn(&Json) -> De<()> = ty::text_document_identifier;
const STRING: fn(&Json) -> De<()> = |v| {
    ty::de_string(v)?;
    Ok(())
};
const REASON: fn(&Json) -> De<()> = |v| {
    ty::de_u32(v)?;
    Ok(())
};
const NUMBER: fn(&Json) -> De<()> = |v| {
    ty::de_f64(v)?;
    Ok(())
};

fn td_position(v: &Json) -> De<()> {
    ty::text_document_position_params(v)
}

fn call_hierarchy_item(v: &Json) -> De<()> {
    let o = ty::as_struct(v, "CallHierarchyItem")?;
    ty::field_req(o, "name", STRING)?;
    ty::field_req(o, "kind", NUMBER)?;
    ty::field_req(o, "uri", ty::de_url)?;
    ty::field_req(o, "range", RANGE)?;
    ty::field_req(o, "selectionRange", RANGE)
}

fn workspace_symbol_item(v: &Json) -> De<()> {
    let o = ty::as_struct(v, "WorkspaceSymbol")?;
    ty::field_req(o, "name", STRING)?;
    ty::field_req(o, "kind", NUMBER)?;
    ty::field_req(o, "location", |v| match v {
        Json::Str(_) => {
            ty::de_url(v)?;
            Ok(())
        }
        _ => ty::location(v),
    })
}

fn reference_context(v: &Json) -> De<()> {
    let o = ty::as_struct(v, "ReferenceContext")?;
    ty::field_req(o, "includeDeclaration", ty::de_bool)
}

fn code_action_context(v: &Json) -> De<()> {
    let o = ty::as_struct(v, "CodeActionContext")?;
    ty::field_req(o, "diagnostics", |v| ty::seq_of(v, |it| Ok(())))
}

fn formatting_options(v: &Json) -> De<()> {
    let o = ty::as_struct(v, "FormattingOptions")?;
    ty::field_req(o, "tabSize", |v| {
        ty::de_u32(v)?;
        Ok(())
    })?;
    ty::field_req(o, "insertSpaces", ty::de_bool)?;
    ty::field_opt(o, "properties", |v| Ok(()))?;
    ty::field_opt(o, "trimTrailingWhitespace", ty::de_bool)?;
    ty::field_opt(o, "insertFinalNewline", ty::de_bool)?;
    ty::field_opt(o, "trimFinalNewlines", ty::de_bool)
}

fn inline_value_context(v: &Json) -> De<()> {
    let o = ty::as_struct(v, "InlineValueContext")?;
    ty::field_req(o, "frameId", NUMBER)?;
    ty::field_req(o, "stoppedLocation", RANGE)
}

fn color(v: &Json) -> De<()> {
    let o = ty::as_struct(v, "Color")?;
    for k in ["red", "green", "blue", "alpha"] {
        ty::field_req(o, k, NUMBER)?;
    }
    Ok(())
}

fn inlay_hint(v: &Json) -> De<()> {
    let o = ty::as_struct(v, "InlayHint")?;
    ty::field_req(o, "position", POSITION)?;
    match o.iter().find(|(k, _)| k == "label") {
        Some((_, Json::Str(_))) => Ok(()),
        Some((_, Json::Obj(_))) => Ok(()),
        Some((_, v)) => Err(
            "data did not match any variant of untagged enum InlayHintLabel".to_string(),
        ),
        None => Err(ty::missing("label")),
    }
}

fn workspace_diagnostic_report(v: &Json) -> De<()> {
    let _ = v;
    Ok(())
}

const SPECS: &[Spec] = &[
    Spec { name: "HoverParams", required: TD_POSITION_REQUIRED(), optional: &[] },
    Spec { name: "CompletionParams", required: TD_POSITION_REQUIRED(), optional: &[] },
    Spec { name: "SignatureHelpParams", required: TD_POSITION_REQUIRED(), optional: &[] },
    Spec { name: "GotoDefinitionParams", required: TD_POSITION_REQUIRED(), optional: &[] },
    Spec { name: "ReferenceParams", required: REFERENCE_REQUIRED(), optional: &[] },
    Spec { name: "DocumentHighlightParams", required: TD_POSITION_REQUIRED(), optional: &[] },
    Spec { name: "DocumentSymbolParams", required: TD_DOCUMENT_REQUIRED(), optional: &[] },
    Spec { name: "CodeActionParams", required: CODE_ACTION_REQUIRED(), optional: &[] },
    Spec { name: "CodeLensParams", required: TD_DOCUMENT_REQUIRED(), optional: &[] },
    Spec { name: "DocumentLinkParams", required: TD_DOCUMENT_REQUIRED(), optional: &[] },
    Spec { name: "DocumentColorParams", required: TD_DOCUMENT_REQUIRED(), optional: &[] },
    Spec { name: "DocumentFormattingParams", required: FORMATTING_REQUIRED(), optional: &[] },
    Spec { name: "DocumentRangeFormattingParams", required: RANGE_FORMATTING_REQUIRED(), optional: &[] },
    Spec { name: "DocumentOnTypeFormattingParams", required: ON_TYPE_REQUIRED(), optional: &[] },
    Spec { name: "RenameParams", required: RENAME_REQUIRED(), optional: &[] },
    Spec { name: "TextDocumentPositionParams", required: TD_POSITION_REQUIRED(), optional: &[] },
    Spec { name: "FoldingRangeParams", required: TD_DOCUMENT_REQUIRED(), optional: &[] },
    Spec { name: "SelectionRangeParams", required: SELECTION_REQUIRED(), optional: &[] },
    Spec { name: "CallHierarchyPrepareParams", required: TD_POSITION_REQUIRED(), optional: &[] },
    Spec { name: "CallHierarchyIncomingCallsParams", required: ITEM_REQUIRED(), optional: &[] },
    Spec { name: "CallHierarchyOutgoingCallsParams", required: ITEM_REQUIRED(), optional: &[] },
    Spec { name: "TypeHierarchyPrepareParams", required: TD_POSITION_REQUIRED(), optional: &[] },
    Spec { name: "TypeHierarchySupertypesParams", required: ITEM_REQUIRED(), optional: &[] },
    Spec { name: "TypeHierarchySubtypesParams", required: ITEM_REQUIRED(), optional: &[] },
    Spec { name: "InlineValueParams", required: INLINE_VALUE_REQUIRED(), optional: &[] },
    Spec { name: "InlayHintParams", required: INLAY_HINT_REQUIRED(), optional: &[] },
    Spec { name: "InlayHint", required: &[], optional: &[] },
    Spec { name: "MonikerParams", required: TD_POSITION_REQUIRED(), optional: &[] },
    Spec { name: "LinkedEditingRangeParams", required: TD_POSITION_REQUIRED(), optional: &[] },
    Spec { name: "SemanticTokensParams", required: TD_DOCUMENT_REQUIRED(), optional: &[] },
    Spec { name: "SemanticTokensDeltaParams", required: DELTA_REQUIRED(), optional: &[] },
    Spec { name: "SemanticTokensRangeParams", required: TD_RANGE_REQUIRED(), optional: &[] },
    Spec { name: "DocumentDiagnosticParams", required: TD_DOCUMENT_REQUIRED(), optional: &[] },
    Spec { name: "WorkspaceDiagnosticParams", required: WORKSPACE_DIAGNOSTIC_REQUIRED(), optional: &[] },
    Spec { name: "WorkspaceSymbolParams", required: QUERY_REQUIRED(), optional: &[] },
    Spec { name: "WorkspaceSymbol", required: WS_SYMBOL_REQUIRED(), optional: &[] },
    Spec { name: "ExecuteCommandParams", required: COMMAND_REQUIRED(), optional: &[] },
    Spec { name: "CreateFilesParams", required: FILES_REQUIRED(), optional: &[] },
    Spec { name: "RenameFilesParams", required: RENAME_FILES_REQUIRED(), optional: &[] },
    Spec { name: "DeleteFilesParams", required: FILES_REQUIRED(), optional: &[] },
    Spec { name: "WillSaveTextDocumentParams", required: WILL_SAVE_REQUIRED(), optional: &[] },
    Spec { name: "ColorPresentationParams", required: COLOR_PRESENTATION_REQUIRED(), optional: &[] },
    Spec { name: "CompletionItem", required: LABEL_REQUIRED(), optional: &[] },
    Spec { name: "CodeAction", required: TITLE_REQUIRED(), optional: &[] },
    Spec { name: "CodeLens", required: LENS_REQUIRED(), optional: &[] },
    Spec { name: "DocumentLink", required: LINK_REQUIRED(), optional: &[] },
];

// The table above needs the validator slices as constants, which is only
// possible with functions returning them.
fn TD_POSITION_REQUIRED() -> &'static [(&'static str, fn(&Json) -> De<()>)] {
    &[("textDocument", TEXT_DOCUMENT), ("position", POSITION)]
}
fn TD_DOCUMENT_REQUIRED() -> &'static [(&'static str, fn(&Json) -> De<()>)] {
    &[("textDocument", TEXT_DOCUMENT)]
}
fn TD_RANGE_REQUIRED() -> &'static [(&'static str, fn(&Json) -> De<()>)] {
    &[("textDocument", TEXT_DOCUMENT), ("range", RANGE)]
}
fn REFERENCE_REQUIRED() -> &'static [(&'static str, fn(&Json) -> De<()>)] {
    &[
        ("context", reference_context),
        ("textDocument", TEXT_DOCUMENT),
        ("position", POSITION),
    ]
}
fn CODE_ACTION_REQUIRED() -> &'static [(&'static str, fn(&Json) -> De<()>)] {
    &[
        ("range", RANGE),
        ("context", code_action_context),
        ("textDocument", TEXT_DOCUMENT),
    ]
}
fn FORMATTING_REQUIRED() -> &'static [(&'static str, fn(&Json) -> De<()>)] {
    &[("options", formatting_options), ("textDocument", TEXT_DOCUMENT)]
}
fn RANGE_FORMATTING_REQUIRED() -> &'static [(&'static str, fn(&Json) -> De<()>)] {
    &[
        ("range", RANGE),
        ("options", formatting_options),
        ("textDocument", TEXT_DOCUMENT),
    ]
}
fn ON_TYPE_REQUIRED() -> &'static [(&'static str, fn(&Json) -> De<()>)] {
