        ("textDocument", TEXT_DOCUMENT),
        ("position", POSITION),
    ]
}
fn RENAME_REQUIRED() -> &'static [(&'static str, fn(&Json) -> De<()>)] {
    &[
        ("newName", STRING),
        ("textDocument", TEXT_DOCUMENT),
        ("position", POSITION),
    ]
}
fn SELECTION_REQUIRED() -> &'static [(&'static str, fn(&Json) -> De<()>)] {
    &[
        ("positions", |v| ty::seq_of(v, POSITION)),
        ("textDocument", TEXT_DOCUMENT),
    ]
}
fn ITEM_REQUIRED() -> &'static [(&'static str, fn(&Json) -> De<()>)] {
    &[("item", call_hierarchy_item)]
}
fn INLINE_VALUE_REQUIRED() -> &'static [(&'static str, fn(&Json) -> De<()>)] {
    &[
        ("range", RANGE),
        ("context", inline_value_context),
