fn spec_for(method: &str) -> Option<&'static Spec> {
    SPECS.iter().find(|s| s.name == spec_name(method))
}

fn spec_name(method: &str) -> &'static str {
    match method {
        "textDocument/hover" => "HoverParams",
        "textDocument/completion" => "CompletionParams",
        "textDocument/signatureHelp" => "SignatureHelpParams",
        "textDocument/declaration" => "GotoDefinitionParams",
        "textDocument/definition" => "GotoDefinitionParams",
        "textDocument/typeDefinition" => "GotoDefinitionParams",
        "textDocument/implementation" => "GotoDefinitionParams",
        "textDocument/references" => "ReferenceParams",
