//! The `check` subcommand: verify that rustowl is able to analyze a target.

use crate::analyze::{self, T_BACKEND};
use crate::cli::Command;
use crate::log;
use crate::toolchain::Toolchain;
use std::path::{Path, PathBuf};

pub fn run(cmd: &Command) -> i32 {
    let (path, all_targets, all_features) = match cmd {
        Command::Check {
            path,
            all_targets,
            all_features,
        } => (path.clone(), *all_targets, *all_features),
        _ => (None, false, false),
    };
    let runtime = crate::toolchain::runtime_dir(None);
    let toolchain = Toolchain::new(&runtime);
    if let Err(_e) = toolchain.ensure() {
        return 1;
    }
    toolchain.cargo();
    toolchain.rustowlc();

    let passed: PathBuf = match path {
        Some(p) => PathBuf::from(p),
        None => std::env::current_dir().unwrap_or_else(|_| PathBuf::from("/")),
    };
    let resolved = analyze::resolve(&toolchain, &passed);
    if !resolved.is_valid() {
        log::warn(
            analyze::T_ANALYZE,
            &format!("Invalid analysis target: {}", passed.to_string_lossy()),
        );
        log::error(analyze::T_ROOT, "Analyze failed");
        return 1;
    }
    log::info(T_BACKEND, "wait 100ms for rust-analyzer");
