//! helper subcommands used by editors to install and check the toolchain.

mod analyze;
mod check;
mod cli;
mod completions;
mod download;
mod json;
mod log;
mod lsp;
mod toolchain;
mod types;
mod url;

use std::io::Write;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let argv0 = args.first().cloned().unwrap_or_default();
    let bin = std::path::Path::new(&argv0)
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| cli::DISPLAY_NAME.to_string());
    let rest: Vec<String> = args.iter().skip(1).cloned().collect();

    let parsed = cli::parse(&bin, &rest);
    log::set_quiet(parsed.quiet);

    let code = match &parsed.command {
        cli::Command::Lsp => {
            lsp::run();
            0
        }
        cli::Command::Check { .. } => check::run(&parsed.command),
        cli::Command::Clean => check::clean(),
        cli::Command::ToolchainNoop => 0,
        cli::Command::ToolchainInstall {
            path,
            skip_rustowl_toolchain,
        } => {
            let runtime = crate::toolchain::runtime_dir(path.as_ref().map(std::path::Path::new));
            let toolchain = crate::toolchain::Toolchain::new(&runtime);
            match toolchain.install(*skip_rustowl_toolchain) {
                Ok(()) => {
                    let _ = toolchain.ensure();
                    0
                }
                Err(_) => 1,
            }
        }
        cli::Command::ToolchainUninstall => {
            let runtime = crate::toolchain::runtime_dir(None);
            let toolchain = crate::toolchain::Toolchain::new(&runtime);
            let _ = toolchain.uninstall();
            0
        }
        cli::Command::Completions(shell) => {
            completions::print(shell);
            0
        }
    };
    let _ = std::io::stdout().flush();
    std::process::exit(code);
}
