addition = '''
// ---------------------------------------------------------------------------
// Flag and subcommand metadata
// ---------------------------------------------------------------------------

struct FlagSpec {
    /// Long name as typed by the user.
    long: &'static str,
    /// Rendering used in usage strings and error messages.
    rendered: &'static str,
    /// The flag may be repeated.
    multiple: bool,
    /// The flag consumes the following argument as its value.
    value: bool,
}

fn scope_flags(scope: Scope) -> &'static [FlagSpec] {
    const HELP: FlagSpec = FlagSpec {
        long: "--help",
        rendered: "--help",
        multiple: false,
        value: false,
    };
    match scope {
        Scope::Root => &[
            FlagSpec {
                long: "--version",
                rendered: "--version",
                multiple: false,
                value: false,
            },
            FlagSpec {
                long: "--quiet",
                rendered: "--quiet...",
                multiple: true,
                value: false,
            },
            FlagSpec {
                long: "--stdio",
                rendered: "--stdio",
                multiple: false,
                value: false,
            },
            HELP,
        ],
        Scope::Check => &[
            FlagSpec {
                long: "--all-targets",
                rendered: "--all-targets",
                multiple: false,
                value: false,
            },
            FlagSpec {
                long: "--all-features",
                rendered: "--all-features",
                multiple: false,
                value: false,
            },
            HELP,
        ],
        Scope::ToolchainInstall => &[
            FlagSpec {
                long: "--path",
                rendered: "--path <path>",
                multiple: false,
                value: true,
            },
            FlagSpec {
                long: "--skip-rustowl-toolchain",
                rendered: "--skip-rustowl-toolchain",
                multiple: false,
                value: false,
            },
            HELP,
        ],
        _ => &[HELP],
    }
}

/// Jaro similarity, used to find "did you mean" candidates.
fn jaro(a: &str, b: &str) -> f64 {
    let s1: Vec<char> = a.chars().collect();
    let s2: Vec<char> = b.chars().collect();
    if s1.is_empty() && s2.is_empty() {
        return 1.0;
    }
    if s1.is_empty() || s2.is_empty() {
        return 0.0;
    }
    if s1 == s2 {
        return 1.0;
    }
    let window = (std::cmp::max(s1.len(), s2.len()) / 2).saturating_sub(1);
    let mut s2_used = vec![false; s2.len()];
    let mut matches = 0usize;
    let mut s1_matched = vec![false; s1.len()];
    for (i, c) in s1.iter().enumerate() {
        let start = i.saturating_sub(window);
        let end = std::cmp::min(i + window + 1, s2.len());
        for j in start..end {
            if !s2_used[j] && s2[j] == *c {
                s2_used[j] = true;
                s1_matched[i] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut k = 0usize;
    for (i, _) in s1.iter().enumerate() {
        if !s1_matched[i] {
            continue;
        }
        while !s2_used[k] {
            k += 1;
        }
        if s1[i] != s2[k] {
            transpositions += 1;
        }
        k += 1;
    }
    let m = matches as f64;
    let t = (transpositions / 2) as f64;
    (m / s1.len() as f64 + m / s2.len() as f64 + (m - t) / m) / 3.0
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    if j <= 0.7 {
        return j;
    }
    let prefix = a
        .chars()
        .zip(b.chars())
        .take(4)
        .take_while(|(x, y)| x == y)
        .count();
    j + prefix as f64 * 0.1 * (1.0 - j)
}

fn did_you_mean(value: &str, candidates: &[&str]) -> Vec<String> {
    let mut found: Vec<(f64, String)> = candidates
        .iter()
        .map(|c| (jaro_winkler(value, c), c.to_string()))
        .filter(|(c, _)| *c > 0.7)
        .collect();
    found.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    found.into_iter().map(|(_, v)| v).collect()
}

fn tip_line(kind: &str, plural: bool, suggestions: &[String]) -> String {
    let quoted: Vec<String> = suggestions
        .iter()
        .map(|s| format!("'{}'", s))
        .collect();
    if plural {
        format!(
            "\\n\\n  tip: some similar {}s exist: {}",
            kind,
            quoted.join(", ")
        )
    } else {
        format!(
            "\\n\\n  tip: a similar {} exists: {}",
            kind,
            quoted.join(", ")
        )
    }
}
