function.arguments:
{"command": "cd /workspace && python3 - <<'PYEOF'
p='src/cli.rs'; s=open(p).read()
start = s.index('pub fn parse(bin: &str, args: &[String]) -> Parsed {')
end = s.index('fn render_used(') if 'fn render_used(' in s else s.index('fn unexpected_argument_full(')
if 'fn render_used(' not in s:
    end = s.index('fn unexpected_argument_full(')
new = '''pub fn parse(bin: &str, args: &[String]) -> Parsed {
    let mut st = State::default();

    let mut i = 0usize;
    while i < args.len() {
        let arg = args[i].clone();
        i += 1;

        // inside `help ...` every argument is a subcommand name
        if st.help_mode.is_some() {
            st.help_args.push(arg);
            continue;
        }

        if st.escaped {
            positional(bin, &mut st, &arg, true);
            st.escaped = false;
            continue;
        }

        if arg == "--" {
            st.escaped = true;
            continue;
        }

        if arg.starts_with("--") && arg.len() > 2 {
            let (name, inline) = match arg.split_once('=') {
                Some((n, v)) => (n.to_string(), Some(v.to_string())),
                None => (arg.clone(), None),
            };
            long_flag(bin, &mut st, &name, inline, &mut i, args);
            continue;
        }

        if arg.starts_with('-') && arg.len() > 1 {
            for c in arg[1..].chars() {
                match c {
                    'h' => print_help(bin, st.scope, false),
                    'V' => {
                        st.want_version = true;
                        if st.scope == Scope::Root && !st.used.iter().any(|u| u == "--version") {
                            st.used.push("--version".to_string());
                        }
                    }
                    'q' if st.scope == Scope::Root => {
                        st.quiet += 1;
                        if !st.used.iter().any(|u| u == "--quiet...") {
                            st.used.push("--quiet...".to_string());
                        }
                    }
                    other => unexpected_argument_short(
                        bin,
                        st.scope,
                        &format!("-{}", other),
                        st.scope.has_positional(),
                    ),
                }
            }
            continue;
        }

        positional(bin, &mut st, &arg, false);
    }

    if let Some(scope) = st.help_mode {
        resolve_help(bin, scope, &st.help_args);
    }

    if st.want_version {
        let text = if st.quiet > 0 {
            format!("{}\\n", VERSION)
        } else {
            format!("{} {}\\n", DISPLAY_NAME, VERSION)
        };
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = lock.write_all(text.as_bytes());
        let _ = lock.flush();
        std::process::exit(0);
    }

    let command = match st.scope {
        Scope::Root => Command::Lsp,
        Scope::Check => Command::Check {
            path: st.path,
            all_targets: st.all_targets,
            all_features: st.all_features,
        },
        Scope::Clean => Command::Clean,
        Scope::Toolchain => Command::ToolchainNoop,
        Scope::ToolchainInstall => Command::ToolchainInstall {
            path: st.install_path,
            skip_rustowl_toolchain: st.skip_rustowl,
        },
        Scope::ToolchainUninstall => Command::ToolchainUninstall,
        Scope::Completions => Command::Completions(st.shell.unwrap()),
        Scope::Help | Scope::ToolchainHelp => Command::Lsp,
    };
    Parsed {
        quiet: st.quiet,
        command,
    }
}

fn smart(bin: &str, st: &State, extra: Option<&str>) -> String {
    let mut used = st.used.clone();
    if let Some(e) = extra {
        if !used.iter().any(|u| u == e) {
            used.push(e.to_string());
        }
    }
    smart_usage(bin, st.scope, &used, st.positional_used)
}

/// Handle a `--flag` argument (possibly with an inline `=value`).
fn long_flag(
    bin: &str,
    st: &mut State,
    name: &str,
    inline: Option<String>,
    next: &mut usize,
    args: &[String],
) {
    let flags = scope_flags(st.scope);
    match flags.iter().find(|f| f.long == name) {
        Some(spec) => {
            if spec.value {
                let value = match inline {
                    Some(v) => Some(v),
                    None => {
                        if *next < args.len() {
                            let v = args[*next].clone();
                            *next += 1;
                            Some(v)
                        } else {
                            None
                        }
                    }
                };
                match value {
                    Some(v) if v.is_empty() => {
                        fail_value_required(st, spec);
                    }
                    Some(v) => {
                        if !st.used.iter().any(|u| u == spec.rendered) {
                            st.used.push(spec.rendered.to_string());
                        }
                        apply_flag(st, spec.long, &v);
                    }
                    None => {
                        fail(
                            &format!(
                                "a value is required for '{}' but none was supplied",
                                spec.rendered
                            ),
                            None,
                        );
                    }
                }
                return;
            }
            if let Some(v) = inline {
                if !st.used.iter().any(|u| u == spec.rendered) {
                    st.used.push(spec.rendered.to_string());
                }
                let u = smart(bin, st, None);
                fail(
                    &format!(
                        "unexpected value '{}' for '{}' found; no more were expected",
                        v, spec.rendered
                    ),
                    Some(&u),
                );
            }
            if !spec.multiple && st.used.iter().any(|u| u == spec.rendered) {
                let u = full_usage(bin, st.scope);
                fail(
                    &format!(
                        "the argument '{}' cannot be used multiple times",
                        spec.rendered
                    ),
                    Some(&u),
                );
            }
