import sys, json, time, os
sys.path.insert(0,'/tmp')
from lsp import LSP

def run(binary, msgs, cwd="/tmp/ws", settle=1.0):
    l = LSP(args=None, cwd=cwd)
    for kind,m,p in msgs:
        if kind=="r": l.request(0,m,p)
        elif kind=="n": l.notify(m,p)
        else:
            l.p.stdin.write(m); l.p.stdin.flush()
    time.sleep(settle)
    out = l.read_all(settle)
    l.p.stdin.close()
    try: rc=l.p.wait(timeout=3)
    except Exception: l.p.kill(); rc=None
    errs=[]
    for e in l.errs:
        e=e.strip()
        if not e: continue
        errs.append(e[e.index('Z')+2:] if e.startswith('20') else e)
    return out, errs, rc

def cmp(label, msgs, cwd="/tmp/ws", settle=1.0):
    a,ea,rca = run("/workspace/executable", msgs, cwd, settle)
    b,eb,rcb = run("/tmp/exedir/executable", msgs, cwd, settle)
    same = json.dumps(a)==json.dumps(b) and json.dumps(ea)==json.dumps(eb) and rca==rcb
    print(("OK   " if same else "DIFF ")+label, "n=%d/%d"%(len(a),len(b)), "rc %s/%s"%(rca,rcb))
    if not same:
        sa=set(map(lambda m: json.dumps(m, sort_keys=True), a)); sb=set(map(lambda m: json.dumps(m, sort_keys=True), b))
        for x in sorted(sa-sb)[:6]: print("   only-orig:", x[:160])
        for x in sorted(sb-sa)[:6]: print("   only-mine:", x[:160])
        if json.dumps(ea)!=json.dumps(eb):
            print("   E-orig:", json.dumps(ea)[:300]); print("   E-mine:", json.dumps(eb)[:300])
    return same
PYEOF
