/// Random UUID (version 4), formatted like `uuid::Uuid::new_v4()`.
pub fn uuid_v4() -> String {
    let mut rng = Rng::new();
    let mut bytes = [0u8; 16];
    for b in bytes.iter_mut() {
        *b = (rng.next() & 0xff) as u8;
