//! LSP work done progress.
//!
//! The analysis reports its own progress to the client when the client asked
//! for it (`window.workDoneProgress`). The token has to be registered first,
//! so the analysis waits for the client's answer before it starts.

use crate::json::{self, Json};
use std::io::Write;
use std::sync::{Arc, Mutex};

/// Server -> client request ids, shared with the main loop.
pub static NEXT_ID: std::sync::atomic::AtomicI32 = std::sync::atomic::AtomicI32::new(0);

/// Requests the server is waiting an answer for.
pub type Pending = Arc<Mutex<Vec<(String, std::sync::mpsc::Sender<()>)>>>;

pub fn new_pending() -> Pending {
    Arc::new(Mutex::new(Vec::new()))
}

/// Notify the waiter of a server request that has been answered.
pub fn resolve(pending: &Pending, id: &Json) {
    let key = id.to_compact();
    let waiter = {
        let mut guard = pending.lock().unwrap();
        match guard.iter().position(|(k, _)| *k == key) {
            Some(pos) => Some(guard.remove(pos).1),
            None => None,
        }
    };
    if let Some(tx) = waiter {
        let _ = tx.send(());
    }
}

pub struct Progress {
    pub token: String,
    pub writer: Arc<Mutex<std::io::Stdout>>,
}

impl Progress {
    /// Register the token with the client and wait for the acknowledgement.
    pub fn create(writer: Arc<Mutex<std::io::Stdout>>, pending: Pending) -> Option<Progress> {
        let token = crate::toolchain::uuid_v4();
        let id = NEXT_ID.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        let (tx, rx) = std::sync::mpsc::channel();
        {
            let mut guard = pending.lock().unwrap();
            guard.push((id.to_string(), tx));
        }
        let mut params = Json::obj();
        params.insert("token", Json::Str(token.clone()));
        let mut obj = Json::obj();
        obj.insert("jsonrpc", Json::Str("2.0".to_string()));
        obj.insert(
            "method",
            Json::Str("window/workDoneProgress/create".to_string()),
        );
        obj.insert("params", params);
        obj.insert("id", Json::Int(id as i64));
        send(&writer, &obj.to_compact());
        match rx.recv() {
            Ok(()) => Some(Progress {
                token,
                writer,
            }),
            Err(_) => None,
        }
    }

    fn notify(&self, value: Json) {
        let mut params = Json::obj();
        params.insert("token", Json::Str(self.token.clone()));
        params.insert("value", value);
        let mut obj = Json::obj();
        obj.insert("jsonrpc", Json::Str("2.0".to_string()));
        obj.insert("method", Json::Str("$/progress".to_string()));
        obj.insert("params", params);
