import sys, json, time; sys.path.insert(0,'/tmp')
from lsp import LSP
def run(binary, uri, sleep_before_reply, total=4.0, extra=None):
    l = LSP(cwd="/tmp/ws")
    l.request(1,"initialize",{"rootUri":uri,"capabilities":{"window":{"workDoneProgress":True}}})
    out=[]
    r1=l.read(3); out.append("init" if r1 else None)
    m=l.read(3)
    if m and m.get("method")=="window/workDoneProgress/create":
        if sleep_before_reply is not None:
            time.sleep(sleep_before_reply)
        l.send({"jsonrpc":"2.0","result":None,"id":m["id"]})
        out.append("create")
    else:
        out.append("nocreate")
    if extra:
        for kind,mm,pp in extra:
            if kind=="n": l.notify(mm,pp)
    end=time.time()+total
    while time.time()<end:
        r=l.read(0.3)
        if r:
            v=r.get("params",{}).get("value",{})
            if r.get("method")=="window/workDoneProgress/create":
                out.append("create2")
            else:
                out.append((v.get("kind"), v.get("message")))
    l.p.stdin.close()
    try: rc=l.p.wait(timeout=3)
    except Exception: l.p.kill(); rc=None
    return out, rc
