actions.command:
cat > /tmp/fakecargo <<'EOF'
#!/bin/sh
echo "$(date +%s.%N) CARGO $*" >> /tmp/cargo_t.log
case "$1" in
  metadata) [ -f /tmp/meta.out ] && cat /tmp/meta.out; exit 0;;
  check) [ -f /tmp/check.out ] && cat /tmp/check.out; exit 0;;
  clean) exit 0;;
esac
EOF
chmod +x /tmp/fakecargo; /tmp/tc.sh; echo "" > /tmp/cargo_t.log
cd /tmp && timeout 30 python3 -c "
import sys,json,time; sys.path.insert(0,'/tmp')
from lsp import *
l=LSP(cwd='/tmp/ws'); l.request(1,'initialize',{'rootUri':'file:///tmp/ws/src/main.rs','capabilities':{}})
l.read(3); time.sleep(1.5)
for e in l.errs: print('  ',repr(e))
l.p.kill()"; echo "--- cargo log:"; python3 -c "
import os
t0=None
for line in open('/tmp/cargo_t.log'):
    p=line.split(); t=float(p[0]); 
    if t0 is None: t0=t
    print('%.2f'%(t-t0), ' '.join(p[1:]))"

